window.DIFGEM_INDEX = [{"id":"def-1","url":"lectures/lecture-01.html#def-1","kind":"def","label":"Def. 1","title":"Топология","text":"Топологией на множестве X называется любая система τ = {T_α} ⊆ 2^X его подмножеств, удовлетворяющая трём аксиомам: множество X и пустое подмножество ∅ принадлежат τ; объединение ⋃_α T_α любого числа множеств из τ принадлежит τ; пересечение ⋂_α T_α любого конечного числа множеств из τ принадлежит τ.","section":"1.1 Открытые множества","source":"Лекция 1"},{"id":"ex-1","url":"lectures/lecture-01.html#ex-1","kind":"example","label":"Ex. 1","title":"Антидискретная и дискретная топологии","text":"Примером топологии на X может служить система τ = {X, ∅}, состоящая из самого множества X и пустого множества ∅. Такая топология τ_a называется антидискретной. Другим примером является дискретная топология τ_d: семейству τ = 2^X принадлежат все подмножества X.","section":"1.1 Открытые множества","source":"Лекция 1"},{"id":"ex-2","url":"lectures/lecture-01.html#ex-2","kind":"example","label":"Ex. 2","title":"Связанное двоеточие","text":"Пусть X = {a, b} — множество из двух точек. Топологическое пространство ⟨X, τ⟩, где τ = {∅, X, {b}}, называется связанным двоеточием.","section":"1.1 Открытые множества","source":"Лекция 1"},{"id":"ex-3","url":"lectures/lecture-01.html#ex-3","kind":"example","label":"Ex. 3","title":"Стандартная топология на прямой","text":"Если X = ℝ, то совокупность τ_st всех открытых интервалов вида (a, b) и их произвольных объединений образует топологию на ℝ. Назовём данную топологию стандартной топологией на ℝ.","section":"1.1 Открытые множества","source":"Лекция 1"},{"id":"ex-4","url":"lectures/lecture-01.html#ex-4","kind":"example","label":"Ex. 4","title":"Топология стрелки","text":"На множестве X = [0, +∞) система τ_→, состоящая из X, пустого множества ∅ и всех лучей вида (a, +∞), a ⩾ 0, образует топологию, называемую стрелкой.","section":"1.1 Открытые множества","source":"Лекция 1"},{"id":"def-2","url":"lectures/lecture-01.html#def-2","kind":"def","label":"Def. 2","title":"Топологическое пространство","text":"Множество X с заданной на нём топологией τ называется топологическим пространством. Топологическое пространство обозначается как пара ⟨X, τ⟩. Множества, принадлежащие системе τ, называются открытыми.","section":"1.1 Открытые множества","source":"Лекция 1"},{"id":"ex-5","url":"lectures/lecture-01.html#ex-5","kind":"example","label":"Ex. 5","title":"Топология конечных дополнений","text":"Будем считать открытыми множествами в X само X, пустое множество ∅, а также все множества, получающиеся выбрасыванием из X конечного числа точек. Такая топология τ_CF называется топологией конечных дополнений.","section":"1.1 Открытые множества","source":"Лекция 1"},{"id":"ml-blocks","url":"lectures/lecture-01.html#ml-blocks","kind":"ml","label":"ИИ","title":"Топология из блоков неразличимых объектов","text":"Абстракция «объявим, какие множества открыты» — это в точности абстракция «объявим, какие объекты мы не умеем различать». Пусть множество объектов X разбито на блоки C_1, …, C_k, внутри которых объекты неразличимы по наблюдаемым признакам. Объявим открытыми все объединения блоков: τ = {\\ ⋃_i ∈ I C_i \\ I ⊆ {1, …, k}\\…","section":"1.1 Открытые множества","source":"Лекция 1"},{"id":"def-3","url":"lectures/lecture-01.html#def-3","kind":"def","label":"Def. 3","title":"Подпространство","text":"Подпространством топологического пространства X называется пара ⟨S, τ_S⟩, где τ_S = {S ∩ T_α}_α и T_α — открытые подмножества в топологии τ_X.","section":"1.2 Индуцированные топологии","source":"Лекция 1"},{"id":"ex-6","url":"lectures/lecture-01.html#ex-6","kind":"example","label":"Ex. 6","title":"Подпространство в топологии стрелки","text":"Пусть X = [0, +∞) и τ_X = τ_→. Тогда S = [0, 1) будет подпространством топологического пространства X с индуцированной топологией τ_S = {∅, S} ∪ {(a, 1): \\ 0 ⩽ a < 1}.","section":"1.2 Индуцированные топологии","source":"Лекция 1"},{"id":"nb-1","url":"lectures/lecture-01.html#nb-1","kind":"nb","label":"NB 1","title":"Открытое в подмножестве не обязано быть открытым в X","text":"Следующий контрпример показывает, что множества, открытые в S ⊆ X, не обязаны быть открытыми в X. Пусть X = ℝ^2 со стандартной топологией и S = ℝ × {0}. Следующее множество открыто в S, но не открыто в X: U = (-1, 1) × {0} = S ∩ big((-1,1) × (-1,1)big)","section":"1.2 Индуцированные топологии","source":"Лекция 1"},{"id":"lm-1","url":"lectures/lecture-01.html#lm-1","kind":"lemma","label":"Lm. 1","title":"Открытые в открытом подпространстве открыты и в X","text":"Открытые множества открытого подпространства S открыты и во всём пространстве X (формальная запись является заодно и доказательством): S ∈ τ_X ⇒ τ_S ⊆ τ_X.","section":"1.2 Индуцированные топологии","source":"Лекция 1"},{"id":"def-4","url":"lectures/lecture-01.html#def-4","kind":"def","label":"Def. 4","title":"Сильнее и слабее","text":"Говорят, что топология τ_2 сильнее (тоньше) топологии τ_1 на множестве X, а топология τ_1 слабее (грубее) топологии τ_2, если всякое подмножество, открытое в топологии τ_1, является открытым и в топологии τ_2.","section":"1.2 Индуцированные топологии","source":"Лекция 1"},{"id":"nb-2","url":"lectures/lecture-01.html#nb-2","kind":"nb","label":"NB 2","title":"Крайние элементы порядка","text":"Среди всех самой слабой является топология τ_a, а самой сильной — τ_d.","section":"1.2 Индуцированные топологии","source":"Лекция 1"},{"id":"lm-2","url":"lectures/lecture-01.html#lm-2","kind":"lemma","label":"Lm. 2","title":"Топология произведения","text":"Множество X × Y с системой τ_X × Y = {⋃_i ∈ I (A_i × B_i): \\ A_i ∈ τ_X,\\ B_i ∈ τ_Y} состоящей из произвольных объединений декартовых произведений открытых множеств, является топологическим пространством. Эта топология называется топологией произведения.","section":"1.2 Индуцированные топологии","source":"Лекция 1"},{"id":"ex-7","url":"lectures/lecture-01.html#ex-7","kind":"example","label":"Ex. 7","title":"Стандартная топология на плоскости","text":"Пространство ℝ^2 можно снабдить структурой топологического пространства со стандартной топологией. Открытыми множествами в ней являются открытые прямоугольники — декартовы произведения вида (a, b) × (c, d) — и их произвольные объединения. Аналогичным образом стандартная топология вводится на ℝ^n.","section":"1.2 Индуцированные топологии","source":"Лекция 1"},{"id":"ml-norms","url":"lectures/lecture-01.html#ml-norms","kind":"ml","label":"ИИ","title":"Выбор нормы не меняет топологию","text":"Отсюда сразу следует полезная вещь про метрики в ML. Замена L_2 на L_∞ (или на L_1) не меняет топологию ℝ^n: множества, которые были открытыми, остаются открытыми, сходящиеся последовательности продолжают сходиться, непрерывные функции остаются непрерывными. Меняется только геометрия — форма шаров, а вместе с ней чи…","section":"1.2 Индуцированные топологии","source":"Лекция 1"},{"id":"ml-sample","url":"lectures/lecture-01.html#ml-sample","kind":"ml","label":"ИИ","title":"На конечной выборке топология дискретна","text":"Второй мостик — про данные. Пусть D = {x_1, …, x_m} ⊆ ℝ^n — выборка из попарно различных точек с индуцированной топологией. Тогда топология на D дискретна: вокруг каждой точки x_k можно взять такой маленький шар, что он не заденет остальные точки, и его след на D — это {x_k}. Значит любое подмножество выборки открыт…","section":"1.2 Индуцированные топологии","source":"Лекция 1"},{"id":"def-5","url":"lectures/lecture-01.html#def-5","kind":"def","label":"Def. 5","title":"Открытая окрестность","text":"Открытой окрестностью (или просто окрестностью) O_P точки P ∈ X называется всякое открытое подмножество X, содержащее точку P.","section":"1.3 Окрестность точки","source":"Лекция 1"},{"id":"nb-3","url":"lectures/lecture-01.html#nb-3","kind":"nb","label":"NB 3","title":"Окрестность существует всегда","text":"У любой точки множества X имеется по крайней мере одна открытая окрестность — само множество X. Наличие других окрестностей определяется введённой на X топологией.","section":"1.3 Окрестность точки","source":"Лекция 1"},{"id":"def-6","url":"lectures/lecture-01.html#def-6","kind":"def","label":"Def. 6","title":"Внутренняя точка","text":"Точка P ∈ X называется внутренней точкой множества S, если существует открытая окрестность O_P точки P, целиком содержащаяся в S: P ∈ O_P ⊆ S.","section":"1.3 Окрестность точки","source":"Лекция 1"},{"id":"def-7","url":"lectures/lecture-01.html#def-7","kind":"def","label":"Def. 7","title":"Внутренность","text":"Внутренностью Int_X(S) множества S называется наибольшее (по включению) открытое подмножество, содержащееся в S.","section":"1.3 Окрестность точки","source":"Лекция 1"},{"id":"lm-3","url":"lectures/lecture-01.html#lm-3","kind":"lemma","label":"Lm. 3","title":"Внутренность существует и состоит из внутренних точек","text":"Всякое подмножество S топологического пространства X обладает внутренностью Int_X(S), которая совпадает со множеством его внутренних точек.","section":"1.3 Окрестность точки","source":"Лекция 1"},{"id":"def-8","url":"lectures/lecture-01.html#def-8","kind":"def","label":"Def. 8","title":"Внешняя точка","text":"Точка P называется внешней точкой множества S, если существует открытая окрестность O_P точки P, целиком содержащаяся в дополнении S^c = X \\ S к S.","section":"1.3 Окрестность точки","source":"Лекция 1"},{"id":"def-9","url":"lectures/lecture-01.html#def-9","kind":"def","label":"Def. 9","title":"Граничная точка","text":"Точка P называется граничной точкой множества S, если каждая открытая окрестность O_P точки P имеет непустое пересечение как с самим S, так и с его дополнением S^c.","section":"1.3 Окрестность точки","source":"Лекция 1"},{"id":"nb-4","url":"lectures/lecture-01.html#nb-4","kind":"nb","label":"NB 4","title":"Обозначение границы","text":"Множество граничных точек S будем обозначать через ∂ S.","section":"1.3 Окрестность точки","source":"Лекция 1"},{"id":"lm-4","url":"lectures/lecture-01.html#lm-4","kind":"lemma","label":"Lm. 4","title":"Разложение пространства на три части","text":"Для каждого подмножества S ⊆ X топологического пространства X имеет место разложение X = Int(S) ∪ Int(S^c) ∪ ∂ S на три попарно непересекающихся множества.","section":"1.3 Окрестность точки","source":"Лекция 1"},{"id":"ml-boundary","url":"lectures/lecture-01.html#ml-boundary","kind":"ml","label":"ИИ","title":"Граница решения и локальная устойчивость","text":"Это разложение — точная формулировка того, что в ML называют границей решения. Пусть A ⊆ X, а классификатор относит точки A к классу 1, точки X \\ A — к классу 0. Назовём его решение локально устойчивым в точке x, если существует открытая окрестность U точки x, все точки которой относятся к тому же классу, что и x. Т…","section":"1.3 Окрестность точки","source":"Лекция 1"},{"id":"def-10","url":"lectures/lecture-01.html#def-10","kind":"def","label":"Def. 10","title":"Замкнутое множество","text":"Подмножество S называется замкнутым в топологическом пространстве ⟨X, τ⟩, если его дополнение является открытым множеством.","section":"1.3 Окрестность точки","source":"Лекция 1"},{"id":"nb-5","url":"lectures/lecture-01.html#nb-5","kind":"nb","label":"NB 5","title":"Граница замкнута","text":"Подмножество ∂ S граничных точек S является замкнутым множеством.","section":"1.3 Окрестность точки","source":"Лекция 1"},{"id":"ex-8","url":"lectures/lecture-01.html#ex-8","kind":"example","label":"Ex. 8","title":"Int, Int дополнения и граница на прямой","text":"Рассмотрим топологическое пространство ⟨ℝ, τ_st⟩ и пусть S = [2, 5) ∪ {7}, тогда Int(S) = (2, 5), Int(S^c) = (-∞, 2) ∪ (5, 7) ∪ (7, +∞) и ∂ S = {2, 5, 7}.","section":"1.3 Окрестность точки","source":"Лекция 1"},{"id":"ex-9","url":"lectures/lecture-01.html#ex-9","kind":"example","label":"Ex. 9","title":"Рациональные числа: Int пусто, граница — вся прямая","text":"Если в качестве множества S в предыдущем примере выбрать множество рациональных чисел ℚ, то Int(ℚ) = ∅ = Int(ℚ^c), а ∂ ℚ = ℝ.","section":"1.3 Окрестность точки","source":"Лекция 1"},{"id":"ex-10","url":"lectures/lecture-01.html#ex-10","kind":"example","label":"Ex. 10","title":"Тот же вопрос в топологии стрелки","text":"Рассмотрим пространство X = [0, +∞) с топологией τ = τ_→ и подмножество S = [2, 5). Тогда Int(S) = ∅, Int(S^c) = (5, +∞) и ∂ S = [0, 5].","section":"1.3 Окрестность точки","source":"Лекция 1"},{"id":"def-11","url":"lectures/lecture-01.html#def-11","kind":"def","label":"Def. 11","title":"Замыкание","text":"Замыканием Cl_X(S) множества S называется наименьшее (по включению) замкнутое множество, содержащее S.","section":"1.3 Окрестность точки","source":"Лекция 1"},{"id":"def-12","url":"lectures/lecture-01.html#def-12","kind":"def","label":"Def. 12","title":"Точка прикосновения","text":"Точка P ∈ X называется точкой прикосновения множества S, если каждая открытая окрестность точки P имеет непустое пересечение с S.","section":"1.3 Окрестность точки","source":"Лекция 1"},{"id":"lm-5","url":"lectures/lecture-01.html#lm-5","kind":"lemma","label":"Lm. 5","title":"Замыкание существует и равно S ∪ ∂S","text":"Всякое подмножество S топологического пространства X обладает замыканием Cl(S), причём Cl(S) = S ∪ ∂ S.","section":"1.3 Окрестность точки","source":"Лекция 1"},{"id":"ex-11","url":"lectures/lecture-01.html#ex-11","kind":"example","label":"Ex. 11","title":"Замыкание множества из Ex. 8","text":"В пространстве ⟨ℝ, τ_st⟩ выберем подмножество S = [2, 5) ∪ {7}, тогда его замыканием будет Cl(S) = [2, 5] ∪ {7}.","section":"1.3 Окрестность точки","source":"Лекция 1"},{"id":"nb-6","url":"lectures/lecture-01.html#nb-6","kind":"nb","label":"NB 6","title":"Открытое и замкнутое — не антонимы","text":"Множество может быть одновременно открытым и замкнутым. Например, в дискретной топологии любое подмножество X открыто, а поскольку его дополнение также открыто, оно является и замкнутым.","section":"1.3 Окрестность точки","source":"Лекция 1"},{"id":"ml-closure","url":"lectures/lecture-01.html#ml-closure","kind":"ml","label":"ИИ","title":"Замыкание, симплекс и softmax","text":"Замыкание — формализация «к чему модель подходит сколь угодно близко». Пусть S — множество точек, на которых модель уверенно отвечает «класс 1». Тогда Cl(S) содержит точки, в любой окрестности которых есть уверенные срабатывания, — включая те, где сама модель не уверена. Разность Cl(S) \\ Int(S) = ∂ S и есть зона, гд…","section":"1.3 Окрестность точки","source":"Лекция 1"},{"id":"def-13","url":"lectures/lecture-01.html#def-13","kind":"def","label":"Def. 13","title":"База топологии","text":"Семейство beta подмножеств X называется базой топологии τ, если beta содержится в τ и для каждой точки P ∈ X и любой её окрестности O_P существует элемент V ∈ beta, такой что P ∈ V ⊆ O_P.","section":"1.4 База и предбаза топологии","source":"Лекция 1"},{"id":"lm-6","url":"lectures/lecture-01.html#lm-6","kind":"lemma","label":"Lm. 6","title":"Критерий базы через объединения","text":"Пусть beta ⊆ τ. Семейство beta является базой топологии τ тогда и только тогда, когда каждый элемент из τ является объединением элементов из beta.","section":"1.4 База и предбаза топологии","source":"Лекция 1"},{"id":"ex-12","url":"lectures/lecture-01.html#ex-12","kind":"example","label":"Ex. 12","title":"Интервалы с рациональными концами","text":"Множество beta_st = {(a, b): a, b ∈ ℚ} — база топологического пространства ⟨ℝ, τ_st⟩.","section":"1.4 База и предбаза топологии","source":"Лекция 1"},{"id":"nb-7","url":"lectures/lecture-01.html#nb-7","kind":"nb","label":"NB 7","title":"Не всякое семейство — база","text":"Не всякое семейство множеств beta является базой некоторой топологии τ. В качестве контрпримера рассмотрим множество X = {a, b, c} и систему beta = {∅, X, {a, b}, {a, c}}.","section":"1.4 База и предбаза топологии","source":"Лекция 1"},{"id":"th-1-1","url":"lectures/lecture-01.html#th-1-1","kind":"theorem","label":"Th. 1.1","title":"Когда семейство порождает топологию","text":"Семейство beta подмножеств X является базой некоторой топологии на X тогда и только тогда, когда ⋃_V ∈ beta V = X и для любых двух элементов V_1, V_2 ∈ beta и каждой точки P ∈ V_1 ∩ V_2 существует элемент W ∈ beta, такой что P ∈ W ⊆ V_1 ∩ V_2.","section":"1.4 База и предбаза топологии","source":"Лекция 1"},{"id":"def-14","url":"lectures/lecture-01.html#def-14","kind":"def","label":"Def. 14","title":"Предбаза","text":"Набор sigma открытых множеств топологического пространства ⟨X, τ⟩ называется предбазой, если следующий набор является базой топологии τ: beta = {V: \\ V = ⋂_i=1^k W_i, W_i ∈ sigma, k ∈ ℕ}.","section":"1.4 База и предбаза топологии","source":"Лекция 1"},{"id":"ml-trees","url":"lectures/lecture-01.html#ml-trees","kind":"ml","label":"ИИ","title":"Решающие деревья строят множества из предбазы","text":"Решающее дерево буквально проходит все три уровня этой иерархии. Каждое разбиение в узле — полупространство вида {x: x_j > t} или {x: x_j < t}, то есть луч по одной координате. Это элементы предбазы стандартной топологии ℝ^n. Путь от корня до листа — конечное пересечение таких лучей, то есть параллелепипед (a_1,b_1)…","section":"1.4 База и предбаза топологии","source":"Лекция 1"},{"id":"ml-summary","url":"lectures/lecture-01.html#ml-summary","kind":"ml","label":"ИИ","title":"Сводка соответствий с ML","text":"Итог лекции на языке ИИ, одной таблицей. Топологический объект Что это в ML Задача листа ∂ A граница решения классификатора; зона неустойчивости 7 Int(A) ∪ Int(A^c) область локально устойчивых предсказаний 7 внутренность симплекса Δ softmax-выходы без нулевых вероятностей 11 топология из блоков неразличимость объект…","section":"Итоги лекции и что дальше","source":"Лекция 1"},{"id":"def-1","url":"lectures/lecture-02.html#def-1","kind":"def","label":"Def. 1","title":"Предельная точка множества","text":"Точка P ∈ X называется предельной точкой множества S ⊆ X, если каждая окрестность точки P содержит хотя бы одну точку из S, отличную от P.","section":"2.1 Аксиомы счётности","source":"Лекция 2"},{"id":"def-2","url":"lectures/lecture-02.html#def-2","kind":"def","label":"Def. 2","title":"Сходимость последовательности","text":"Говорят, что последовательность точек {P_i}_i=1^∞ сходится к некоторой точке Q, если любая окрестность Q содержит все члены данной последовательности, начиная с некоторого номера.","section":"2.1 Аксиомы счётности","source":"Лекция 2"},{"id":"nb-1","url":"lectures/lecture-02.html#nb-1","kind":"nb","label":"NB 1","title":"Предельная точка и последовательности","text":"В метрических пространствах точка P является предельной для S тогда и только тогда, когда существует сходящаяся к ней последовательность точек из S \\ {P}. Существование сходящейся к P последовательности из самого S характеризует принадлежность P замыканию overlineS. В произвольном топологическом пространстве это не …","section":"2.1 Аксиомы счётности","source":"Лекция 2"},{"id":"ex-1","url":"lectures/lecture-02.html#ex-1","kind":"example","label":"Ex. 1","title":"Топология счётных дополнений","text":"Рассмотрим топологию счётных дополнений на X = [0,1]: τ_CC = {∅} ∪ {U ⊆ X: X \\ U не более чем счётно}. В пространстве ⟨X, τ_CC⟩ сходящимися будут только стационарные последовательности. Для любой точки P ∈ X множество S = X \\ {P} имеет P своей предельной точкой: каждая её окрестность содержит точки S. Однако никакая…","section":"2.1 Аксиомы счётности","source":"Лекция 2"},{"id":"def-3","url":"lectures/lecture-02.html#def-3","kind":"def","label":"Def. 3","title":"Фундаментальная система окрестностей","text":"Система окрестностей sigma_P точки P называется фундаментальной системой окрестностей (локальной базой) точки P, если для каждого открытого множества S, содержащего точку P, найдётся окрестность из системы sigma_P, целиком лежащая в S.","section":"2.1 Аксиомы счётности","source":"Лекция 2"},{"id":"def-4","url":"lectures/lecture-02.html#def-4","kind":"def","label":"Def. 4","title":"Первая аксиома счётности","text":"Пространство X, каждая точка которого имеет не более чем счётную фундаментальную систему окрестностей, называется пространством с первой аксиомой счётности.","section":"2.1 Аксиомы счётности","source":"Лекция 2"},{"id":"lm-1","url":"lectures/lecture-02.html#lm-1","kind":"lemma","label":"Lm. 1","title":"Предельные точки — пределы последовательностей","text":"В топологических пространствах с первой аксиомой счётности каждая предельная точка Q произвольного множества S может быть представлена как предел некоторой последовательности точек из S \\ {Q}.","section":"2.1 Аксиомы счётности","source":"Лекция 2"},{"id":"ml-sequences","url":"lectures/lecture-02.html#ml-sequences","kind":"ml","label":"ИИ","title":"Почему в анализе обучения хватает последовательностей","text":"Почти весь анализ сходимости в ML — это рассуждения о последовательностях: итерации градиентного спуска theta_1, theta_2, …, лосс по эпохам, оценки по растущей выборке. Lm. 1 объясняет, почему этого хватает. Пространство параметров ℝ^n метрическое, значит удовлетворяет первой аксиоме счётности, и замкнутость, предел…","section":"2.1 Аксиомы счётности","source":"Лекция 2"},{"id":"def-5","url":"lectures/lecture-02.html#def-5","kind":"def","label":"Def. 5","title":"Вторая аксиома счётности","text":"Топологическое пространство, в котором существует база, содержащая не более чем счётное число элементов, называется пространством со второй аксиомой счётности.","section":"2.1 Аксиомы счётности","source":"Лекция 2"},{"id":"def-6","url":"lectures/lecture-02.html#def-6","kind":"def","label":"Def. 6","title":"Всюду плотное множество","text":"Множество S ⊆ X называется всюду плотным в X, если overlineS = X. Эквивалентно, каждое непустое открытое подмножество X пересекается с S.","section":"2.1 Аксиомы счётности","source":"Лекция 2"},{"id":"th-2-1","url":"lectures/lecture-02.html#th-2-1","kind":"theorem","label":"Th 2.1","title":"Счётная база даёт счётное плотное множество","text":"Топологическое пространство со второй аксиомой счётности содержит не более чем счётное всюду плотное подмножество S ⊆ X.","section":"2.1 Аксиомы счётности","source":"Лекция 2"},{"id":"def-7","url":"lectures/lecture-02.html#def-7","kind":"def","label":"Def. 7","title":"Сепарабельное пространство","text":"Топологическое пространство X, содержащее не более чем счётное всюду плотное подмножество, называется сепарабельным.","section":"2.1 Аксиомы счётности","source":"Лекция 2"},{"id":"nb-2","url":"lectures/lecture-02.html#nb-2","kind":"nb","label":"NB 2","title":"Вторая аксиома влечёт сепарабельность","text":"Таким образом, всякое топологическое пространство со второй аксиомой счётности является сепарабельным. Обратное, вообще говоря, неверно.","section":"2.1 Аксиомы счётности","source":"Лекция 2"},{"id":"ex-2","url":"lectures/lecture-02.html#ex-2","kind":"example","label":"Ex. 2","title":"Сепарабельно, но без счётной базы","text":"Пусть X — несчётное множество с топологией конечных дополнений τ_CF. Каждое непустое открытое множество плотно в X, поскольку любые два непустых открытых множества пересекаются. Любое счётно бесконечное подмножество S ⊆ X также плотно: оно не может целиком лежать в конечном дополнении непустого открытого множества. …","section":"2.1 Аксиомы счётности","source":"Лекция 2"},{"id":"ml-separable","url":"lectures/lecture-02.html#ml-separable","kind":"ml","label":"ИИ","title":"Сепарабельность и универсальная аппроксимация","text":"Сепарабельность — математическая причина, по которой аппроксимация вообще возможна. Пространство C[0,1] непрерывных функций на отрезке сепарабельно: многочлены с рациональными коэффициентами образуют счётное всюду плотное множество (теорема Вейерштрасса плюс плотность ℚ). То есть любую непрерывную функцию можно скол…","section":"2.1 Аксиомы счётности","source":"Лекция 2"},{"id":"def-8","url":"lectures/lecture-02.html#def-8","kind":"def","label":"Def. 8","title":"Покрытие","text":"Система подмножеств {U_α} множества X называется покрытием множества X, если ⋃_α U_α = X.","section":"2.2 Покрытия, компактность и паракомпактность","source":"Лекция 2"},{"id":"def-9","url":"lectures/lecture-02.html#def-9","kind":"def","label":"Def. 9","title":"Открытое покрытие и подпокрытие","text":"Открытым (замкнутым) покрытием топологического пространства называется покрытие, состоящее из открытых (замкнутых) множеств. Подсемейство покрытия, которое по-прежнему покрывает всё пространство, называется подпокрытием.","section":"2.2 Покрытия, компактность и паракомпактность","source":"Лекция 2"},{"id":"th-2-2","url":"lectures/lecture-02.html#th-2-2","kind":"theorem","label":"Th 2.2","title":"Счётная база даёт счётные подпокрытия","text":"Если топологическое пространство обладает не более чем счётной базой (вторая аксиома счётности), то из любого его открытого покрытия можно выбрать конечное или счётное подпокрытие.","section":"2.2 Покрытия, компактность и паракомпактность","source":"Лекция 2"},{"id":"def-10","url":"lectures/lecture-02.html#def-10","kind":"def","label":"Def. 10","title":"Компактность","text":"Топологическое пространство T, любое открытое покрытие которого содержит конечное подпокрытие, называется компактным.","section":"2.2 Покрытия, компактность и паракомпактность","source":"Лекция 2"},{"id":"ex-3","url":"lectures/lecture-02.html#ex-3","kind":"example","label":"Ex. 3","title":"Окружность, сфера, тор","text":"Окружность S^1, сфера S^2 и тор T^2 = S^1 × S^1 компактны по теореме Гейне–Бореля: они замкнуты и ограничены в ℝ^2, ℝ^3 и ℝ^4 соответственно.","section":"2.2 Покрытия, компактность и паракомпактность","source":"Лекция 2"},{"id":"ex-4","url":"lectures/lecture-02.html#ex-4","kind":"example","label":"Ex. 4","title":"Прямая некомпактна","text":"Прямая ℝ некомпактна: открытое покрытие {(-n, n): n ⩾ 1} не содержит конечного подпокрытия, поскольку объединение любого конечного числа его элементов ограничено.","section":"2.2 Покрытия, компактность и паракомпактность","source":"Лекция 2"},{"id":"ml-compact","url":"lectures/lecture-02.html#ml-compact","kind":"ml","label":"ИИ","title":"Некомпактность и минимумы лосса","text":"Некомпактность ℝ^n — не абстракция, она ломает обучение моделей. Классический случай — логистическая регрессия на линейно разделимых данных. Лосс L(w) = Σ_i log(1 + e^-y_i ⟨w, x_i⟩) можно сделать сколь угодно близким к нулю, растягивая разделяющий вектор: L(c cdot w) → 0 при c → ∞. Но нуля он не достигает ни при как…","section":"2.2 Покрытия, компактность и паракомпактность","source":"Лекция 2"},{"id":"def-11","url":"lectures/lecture-02.html#def-11","kind":"def","label":"Def. 11","title":"Уточнение покрытия","text":"Покрытие mathcalV пространства X называется уточнением покрытия mathcalU, если для каждого V ∈ mathcalV существует U ∈ mathcalU с V ⊆ U. Элементы уточнения не обязаны принадлежать исходному покрытию.","section":"2.2 Покрытия, компактность и паракомпактность","source":"Лекция 2"},{"id":"def-12","url":"lectures/lecture-02.html#def-12","kind":"def","label":"Def. 12","title":"Локально конечное семейство","text":"Семейство подмножеств mathcalV пространства X называется локально конечным, если у каждой точки P ∈ X есть окрестность, пересекающая лишь конечное число элементов mathcalV.","section":"2.2 Покрытия, компактность и паракомпактность","source":"Лекция 2"},{"id":"ex-5","url":"lectures/lecture-02.html#ex-5","kind":"example","label":"Ex. 5","title":"Локально конечное покрытие прямой","text":"Покрытие прямой интервалами U_n = (n-1, n+1), n ∈ ℤ, локально конечно: окрестность (x - 1, x + 1) точки x пересекает U_n лишь при |n - x| < 2, а таких целых n конечное число.","section":"2.2 Покрытия, компактность и паракомпактность","source":"Лекция 2"},{"id":"def-13","url":"lectures/lecture-02.html#def-13","kind":"def","label":"Def. 13","title":"Паракомпактность","text":"Топологическое пространство X называется паракомпактным, если каждое его открытое покрытие имеет открытое локально конечное уточнение.","section":"2.2 Покрытия, компактность и паракомпактность","source":"Лекция 2"},{"id":"nb-3","url":"lectures/lecture-02.html#nb-3","kind":"nb","label":"NB 3","title":"Компактное паракомпактно","text":"Всякое компактное пространство паракомпактно: конечное открытое подпокрытие является локально конечным уточнением исходного покрытия.","section":"2.2 Покрытия, компактность и паракомпактность","source":"Лекция 2"},{"id":"ml-partition","url":"lectures/lecture-02.html#ml-partition","kind":"ml","label":"ИИ","title":"Локальная конечность и смеси экспертов","text":"Разбиение единицы — прямой математический родственник смеси экспертов (mixture of experts). Там есть набор локальных моделей и функции-гейты g_k(x) ⩾ 0 с Σ_k g_k(x) = 1, и ответ — взвешенная сумма Σ_k g_k(x) f_k(x). Это ровно склейка локальных объектов в глобальный по разбиению единицы. А локальная конечность из Def…","section":"2.2 Покрытия, компактность и паракомпактность","source":"Лекция 2"},{"id":"def-14","url":"lectures/lecture-02.html#def-14","kind":"def","label":"Def. 14","title":"Аксиома T₁","text":"Для любых двух различных точек P и Q топологического пространства T существует окрестность O_P точки P, не содержащая точку Q, и окрестность O_Q точки Q, не содержащая P. Пространства, удовлетворяющие данной аксиоме, называются T_1-пространствами.","section":"2.3 Аксиомы отделимости","source":"Лекция 2"},{"id":"ex-6","url":"lectures/lecture-02.html#ex-6","kind":"example","label":"Ex. 6","title":"Связанное двоеточие не T₁","text":"Примером топологии, не удовлетворяющей данной аксиоме, является связанное двоеточие: X = {a, b}, τ = {∅, {a}, {a, b}}. Единственная окрестность точки b — всё X, поэтому она содержит a.","section":"2.3 Аксиомы отделимости","source":"Лекция 2"},{"id":"lm-2","url":"lectures/lecture-02.html#lm-2","kind":"lemma","label":"Lm. 2","title":"В T₁ точки замкнуты","text":"В T_1-пространствах любое одноточечное множество замкнуто.","section":"2.3 Аксиомы отделимости","source":"Лекция 2"},{"id":"def-15","url":"lectures/lecture-02.html#def-15","kind":"def","label":"Def. 15","title":"Аксиома T₂, хаусдорфовость","text":"Любые две различные точки P и Q топологического пространства T имеют непересекающиеся окрестности O_P и O_Q. Пространства, удовлетворяющие данной аксиоме, называются T_2-пространствами, или хаусдорфовыми.","section":"2.3 Аксиомы отделимости","source":"Лекция 2"},{"id":"ex-7","url":"lectures/lecture-02.html#ex-7","kind":"example","label":"Ex. 7","title":"Rⁿ хаусдорфово","text":"Пространство ℝ^n со стандартной топологией хаусдорфово: для P ≠ Q шары с центрами P, Q и радиусом \\|P - Q\\|/3 являются непересекающимися окрестностями этих точек.","section":"2.3 Аксиомы отделимости","source":"Лекция 2"},{"id":"nb-4","url":"lectures/lecture-02.html#nb-4","kind":"nb","label":"NB 4","title":"T₂ влечёт T₁, обратное неверно","text":"Всякое хаусдорфово пространство является T_1-пространством: если P ∈ O_P, Q ∈ O_Q и O_P ∩ O_Q = ∅, то Q ∉ O_P и P ∉ O_Q. Обратное неверно: контрпримером является отрезок [a, b], a < b, с топологией счётных дополнений τ_CC. Дополнения одноточечных множеств открыты, поэтому выполнена аксиома T_1. Однако любые два непу…","section":"2.3 Аксиомы отделимости","source":"Лекция 2"},{"id":"nb-5","url":"lectures/lecture-02.html#nb-5","kind":"nb","label":"NB 5","title":"T₃ и T₄","text":"Более сильные аксиомы отделимости также предполагают T_1. Аксиома T_3 (регулярность) требует, чтобы любую точку и любое не содержащее её замкнутое множество можно было включить в непересекающиеся открытые множества. Аксиома T_4 (нормальность) предъявляет такое требование к любым двум непересекающимся замкнутым множе…","section":"2.3 Аксиомы отделимости","source":"Лекция 2"},{"id":"ml-hausdorff","url":"lectures/lecture-02.html#ml-hausdorff","kind":"ml","label":"ИИ","title":"Коллапс представлений и нехаусдорфовость","text":"Хаусдорфовость — условие, при котором фраза «обучение сходится к решению» вообще осмысленна: только в T_2-пространстве у последовательности не больше одного предела. Пространства параметров и эмбеддингов ℝ^n хаусдорфовы, поэтому мы спокойно говорим о «пределе» итераций. А вот топология, которую на объектах задаёт об…","section":"2.3 Аксиомы отделимости","source":"Лекция 2"},{"id":"ml-preimage","url":"lectures/lecture-03.html#ml-preimage","kind":"ml","label":"ИИ","title":"Прообраз — это область решений","text":"Прообраз — естественный язык для описания того, что делает модель. Если классификатор — отображение f: ℝ^n → {кошка, собака}, то область, которую модель считает кошками, — это прообраз f^-1({кошка}). Свойства из этого раздела дают полезные тождества: область «кошка или собака» — объединение прообразов, а область, гд…","section":"3.1 Свойства прообразов отображения","source":"Лекция 3"},{"id":"def-1","url":"lectures/lecture-03.html#def-1","kind":"def","label":"Def. 1","title":"Непрерывность в точке","text":"Отображение f: X → Y непрерывно в точке x ∈ X, если для любой окрестности V точки f(x) существует окрестность U точки x, такая что f(U) ⊆ V.","section":"3.2 Непрерывные отображения","source":"Лекция 3"},{"id":"nb-1","url":"lectures/lecture-03.html#nb-1","kind":"nb","label":"NB 1","title":"Непрерывность на всём пространстве","text":"Отображение непрерывно на X, если оно непрерывно в каждой точке пространства X.","section":"3.2 Непрерывные отображения","source":"Лекция 3"},{"id":"th-3-1","url":"lectures/lecture-03.html#th-3-1","kind":"theorem","label":"Th. 3.1","title":"Критерий непрерывности через прообразы","text":"Отображение f: X → Y непрерывно тогда и только тогда, когда прообраз каждого открытого множества в Y открыт в X.","section":"3.2 Непрерывные отображения","source":"Лекция 3"},{"id":"ex-1","url":"lectures/lecture-03.html#ex-1","kind":"example","label":"Ex. 1","title":"Примеры непрерывных отображений","text":"Примеры непрерывных отображений (множество V открыто в Y): тождественное отображение id_X: \\ id_X^-1(V) = V; постоянное отображение const_y_0: x mapsto y_0, \\ const_y_0^-1(V) = begincases X, & y_0 ∈ V, \\\\ ∅, & y_0 ∉ V; endcases вложение в подпространство j: A hookrightarrow X, \\ j^-1(V) = A ∩ V; проекция на сомножит…","section":"3.2 Непрерывные отображения","source":"Лекция 3"},{"id":"lm-1","url":"lectures/lecture-03.html#lm-1","kind":"lemma","label":"Lm. 1","title":"Композиция непрерывных непрерывна","text":"Композиция непрерывных отображений f: X → Y и g: Y → Z непрерывна.","section":"3.2 Непрерывные отображения","source":"Лекция 3"},{"id":"cor-1","url":"lectures/lecture-03.html#cor-1","kind":"lemma","label":"Следствие 1","title":"Критерий через замкнутые множества","text":"Отображение f: X → Y непрерывно тогда и только тогда, когда прообраз каждого замкнутого множества в Y замкнут в X.","section":"3.2 Непрерывные отображения","source":"Лекция 3"},{"id":"lm-2","url":"lectures/lecture-03.html#lm-2","kind":"lemma","label":"Lm. 2","title":"Критерий через замыкания","text":"Отображение f: X → Y непрерывно тогда и только тогда, когда ∀ A ⊆ X fbig(Cl_X(A)big) ⊆ Cl_Ybig(f(A)big).","section":"3.2 Непрерывные отображения","source":"Лекция 3"},{"id":"nb-2","url":"lectures/lecture-03.html#nb-2","kind":"nb","label":"NB 2","title":"Непрерывное не обязано быть открытым","text":"Непрерывное отображение не обязательно переводит открытые множества в открытые. Например, непрерывно отображение j: ℝ_st → ℝ^2_st, j(x) = (x, 0).","section":"3.2 Непрерывные отображения","source":"Лекция 3"},{"id":"nb-3","url":"lectures/lecture-03.html#nb-3","kind":"nb","label":"NB 3","title":"Прообраз топологии","text":"Для отображения множеств f: X → Y и топологии τ_Y семейство f^-1(τ_Y) = {f^-1(V): V ∈ τ_Y} является топологией на X. Если на X задана топология τ_X, то по критерию непрерывность f равносильна условию f^-1(τ_Y) ⊆ τ_X.","section":"3.2 Непрерывные отображения","source":"Лекция 3"},{"id":"th-3-2","url":"lectures/lecture-03.html#th-3-2","kind":"theorem","label":"Th. 3.2","title":"Непрерывный образ компакта компактен","text":"Пусть f: X → Y непрерывно, а K ⊆ X — компактно. Тогда образ f(K) компактен в топологии подпространства.","section":"3.2 Непрерывные отображения","source":"Лекция 3"},{"id":"ml-continuity","url":"lectures/lecture-03.html#ml-continuity","kind":"ml","label":"ИИ","title":"Непрерывность моделей и почему argmax разрывен","text":"Сети непрерывны по Lm. 1. Каждый слой — композиция аффинного отображения и поэлементной нелинейности вроде ReLU, обе непрерывны, значит непрерывна и вся сеть. По Th. 3.2 на компактном множестве входов (например, картинки с пикселями в [0,1]) выходы сети ограничены, а непрерывный лосс достигает минимума — это закрыва…","section":"3.2 Непрерывные отображения","source":"Лекция 3"},{"id":"def-2","url":"lectures/lecture-03.html#def-2","kind":"def","label":"Def. 2","title":"Гомеоморфизм","text":"Биекция f: X → Y называется гомеоморфизмом, если f и f^-1: Y → X непрерывны. Пространства X и Y, между которыми существует хотя бы один гомеоморфизм, называются гомеоморфными. При этом пишут X simeq Y.","section":"3.3 Гомеоморфизмы","source":"Лекция 3"},{"id":"ex-2","url":"lectures/lecture-03.html#ex-2","kind":"example","label":"Ex. 2","title":"Непрерывной биекции недостаточно","text":"Непрерывной биекции недостаточно. Для X = {p, q} тождественное отображение f: (X, τ_d) → (X, τ_a), f(x) = x, непрерывно. Однако обратное отображение g = f^-1 не является непрерывным: множество {p} открыто в дискретной топологии, но его прообраз не открыт в антидискретной топологии. g^-1({p}) = {p}","section":"3.3 Гомеоморфизмы","source":"Лекция 3"},{"id":"lm-3","url":"lectures/lecture-03.html#lm-3","kind":"lemma","label":"Lm. 3","title":"Гомеоморфизм — непрерывная открытая биекция","text":"Непрерывная биекция f: X → Y является гомеоморфизмом тогда и только тогда, когда образы открытых множеств открыты.","section":"3.3 Гомеоморфизмы","source":"Лекция 3"},{"id":"nb-4","url":"lectures/lecture-03.html#nb-4","kind":"nb","label":"NB 4","title":"Гомеоморфность — эквивалентность","text":"Гомеоморфность — отношение эквивалентности.","section":"3.3 Гомеоморфизмы","source":"Лекция 3"},{"id":"ex-3","url":"lectures/lecture-03.html#ex-3","kind":"example","label":"Ex. 3","title":"Интервал гомеоморфен прямой","text":"Гомеоморфизм интервала и прямой задаётся отображением tg: (-(pi)/(2), (pi)/(2)) → ℝ_st. При a < b линейная замена переменной даёт (a, b) simeq ℝ_st.","section":"3.3 Гомеоморфизмы","source":"Лекция 3"},{"id":"lm-4","url":"lectures/lecture-03.html#lm-4","kind":"lemma","label":"Lm. 4","title":"Компактность сохраняется гомеоморфизмами","text":"Гомеоморфные пространства одновременно компактны или некомпактны.","section":"3.3 Гомеоморфизмы","source":"Лекция 3"},{"id":"ex-4","url":"lectures/lecture-03.html#ex-4","kind":"example","label":"Ex. 4","title":"Отрезок не гомеоморфен интервалу","text":"При a < b отрезок [a, b] не гомеоморфен интервалу (a, b). Отрезок компактен по теореме Гейне–Бореля. Если бы интервал был компактен, его непрерывный образ при указанном выше гомеоморфизме — вся ℝ — тоже был бы компактен, что противоречит доказанной в предыдущей лекции некомпактности ℝ.","section":"3.3 Гомеоморфизмы","source":"Лекция 3"},{"id":"def-3","url":"lectures/lecture-03.html#def-3","kind":"def","label":"Def. 3","title":"Топологический инвариант","text":"Топологический инвариант — свойство пространства, сохраняющееся при гомеоморфизмах.","section":"3.3 Гомеоморфизмы","source":"Лекция 3"},{"id":"lm-5","url":"lectures/lecture-03.html#lm-5","kind":"lemma","label":"Lm. 5","title":"Список инвариантов","text":"Топологическими инвариантами являются компактность, первая и вторая аксиомы счётности и аксиомы отделимости T_1 и T_2.","section":"3.3 Гомеоморфизмы","source":"Лекция 3"},{"id":"ml-flows","url":"lectures/lecture-03.html#ml-flows","kind":"ml","label":"ИИ","title":"Нормализующие потоки — гомеоморфизмы","text":"Обратимые сети — это гомеоморфизмы, и у них есть топологические ограничения. Нормализующие потоки и neural ODE переводят простое распределение, обычно гауссовское на ℝ^n, в распределение данных обратимым непрерывным отображением с непрерывным обратным, то есть гомеоморфизмом. По Lm. 5 такое отображение сохраняет топ…","section":"3.3 Гомеоморфизмы","source":"Лекция 3"},{"id":"def-1","url":"lectures/lecture-04.html#def-1","kind":"def","label":"Def. 1","title":"Связное пространство","text":"Топологическое пространство X называется связным, если его нельзя представить в виде объединения двух непустых непересекающихся открытых множеств.","section":"4.1 Связность и линейная связность","source":"Лекция 4"},{"id":"ex-1","url":"lectures/lecture-04.html#ex-1","kind":"example","label":"Ex. 1","title":"Связные пространства","text":"Примеры связных пространств: ⟨X, τ_a⟩ — антидискретное пространство; ℝ_st — прямая со стандартной топологией; ⟨(0,1), τ_CF⟩ — коконечная топология на (0,1); ⟨[0, +∞), τ_→⟩ — луч с топологией «стрелка».","section":"4.1 Связность и линейная связность","source":"Лекция 4"},{"id":"def-2","url":"lectures/lecture-04.html#def-2","kind":"def","label":"Def. 2","title":"Связное подмножество","text":"Подмножество A ⊆ X называется связным, если оно связно как пространство с индуцированной топологией. В его разделении открытость частей понимается относительно A.","section":"4.1 Связность и линейная связность","source":"Лекция 4"},{"id":"lm-1","url":"lectures/lecture-04.html#lm-1","kind":"lemma","label":"Lm. 1","title":"Связность через открыто-замкнутые множества","text":"Топологическое пространство связно тогда и только тогда, когда единственными множествами, открытыми и замкнутыми одновременно, являются ∅ и X.","section":"4.1 Связность и линейная связность","source":"Лекция 4"},{"id":"ex-2","url":"lectures/lecture-04.html#ex-2","kind":"example","label":"Ex. 2","title":"Несвязные пространства","text":"Примеры несвязных топологических пространств: ⟨X, τ_d⟩ — дискретное пространство; ℝ_st \\ {0} — прямая с выколотой точкой; X = A ⊔ B, где A, B ∈ τ_X непусты.","section":"4.1 Связность и линейная связность","source":"Лекция 4"},{"id":"def-3","url":"lectures/lecture-04.html#def-3","kind":"def","label":"Def. 3","title":"Компонента связности","text":"Компонентой связности пространства X называется всякое его непустое связное подмножество, не содержащееся (строго) ни в каком другом связном подмножестве пространства X.","section":"4.1 Связность и линейная связность","source":"Лекция 4"},{"id":"th-4-1","url":"lectures/lecture-04.html#th-4-1","kind":"theorem","label":"Th. 4.1","title":"Непрерывный образ связного связен","text":"Пусть X и Y — топологические пространства и sigma: X → Y — непрерывное отображение. Тогда, если X связно, то и sigma(X) также связно.","section":"4.1 Связность и линейная связность","source":"Лекция 4"},{"id":"lm-2","url":"lectures/lecture-04.html#lm-2","kind":"lemma","label":"Lm. 2","title":"Связное множество не разрезать","text":"Пусть X — топологическое пространство, а U и V — два непересекающихся открытых подмножества X. Если A — связное подмножество X, лежащее в U ⊔ V, тогда или A ⊆ U, или A ⊆ V.","section":"4.1 Связность и линейная связность","source":"Лекция 4"},{"id":"lm-3","url":"lectures/lecture-04.html#lm-3","kind":"lemma","label":"Lm. 3","title":"Объединение связных с общей точкой","text":"Пусть {S_α} — непустое семейство связных подмножеств топологического пространства X, имеющих общую точку P. Тогда ⋃_α S_α связно.","section":"4.1 Связность и линейная связность","source":"Лекция 4"},{"id":"nb-1","url":"lectures/lecture-04.html#nb-1","kind":"nb","label":"NB 1","title":"Связность — инвариант","text":"Пространство, гомеоморфное связному пространству, связно.","section":"4.1 Связность и линейная связность","source":"Лекция 4"},{"id":"def-4","url":"lectures/lecture-04.html#def-4","kind":"def","label":"Def. 4","title":"Кривая (путь)","text":"Кривой (или путём) на X из точки P в точку Q называется непрерывное отображение gamma: I = [0,1] → X, такое что gamma(0) = P и gamma(1) = Q.","section":"4.1 Связность и линейная связность","source":"Лекция 4"},{"id":"def-5","url":"lectures/lecture-04.html#def-5","kind":"def","label":"Def. 5","title":"Линейная связность","text":"Топологическое пространство X называется линейно связным, если для любых точек P, Q ∈ X существует кривая в X, соединяющая эти точки.","section":"4.1 Связность и линейная связность","source":"Лекция 4"},{"id":"lm-4","url":"lectures/lecture-04.html#lm-4","kind":"lemma","label":"Lm. 4","title":"Линейно связное связно","text":"Если топологическое пространство X линейно связно, то оно связно.","section":"4.1 Связность и линейная связность","source":"Лекция 4"},{"id":"ml-connected","url":"lectures/lecture-04.html#ml-connected","kind":"ml","label":"ИИ","title":"Связность и генеративные модели","text":"Непрерывный классификатор с дискретным выходом постоянен. Пространство входов ℝ^n связно, а значит по Th. 4.1 непрерывное f: ℝ^n → {0, 1} принимает одно значение. Это закрывает вопрос, оставленный в лекции 3: разрывы argmax неизбежны, и живут они на границе решения (задачи 4.2.4 и 4.2.6* листка). Генератор не может …","section":"4.1 Связность и линейная связность","source":"Лекция 4"},{"id":"def-6","url":"lectures/lecture-04.html#def-6","kind":"def","label":"Def. 6","title":"Локально евклидово пространство","text":"Топологическое пространство ⟨X, τ⟩ называется локально евклидовым пространством размерности n, если каждая точка P ∈ X имеет открытую окрестность в X, гомеоморфную ℝ^n_st.","section":"4.2 Топологическое многообразие","source":"Лекция 4"},{"id":"th-4-2","url":"lectures/lecture-04.html#th-4-2","kind":"theorem","label":"Th. 4.2","title":"Теорема Брауэра об инвариантности размерности","text":"(Брауэр.) Если непустые открытые множества U ⊆ ℝ^n_st и V ⊆ ℝ^m_st гомеоморфны, то m = n.","section":"4.2 Топологическое многообразие","source":"Лекция 4"},{"id":"def-7","url":"lectures/lecture-04.html#def-7","kind":"def","label":"Def. 7","title":"Топологическое многообразие","text":"Топологическим многообразием размерности n называется паракомпактное хаусдорфово пространство, локально евклидово размерности n. Многообразия рассматриваются без края.","section":"4.2 Топологическое многообразие","source":"Лекция 4"},{"id":"ex-3","url":"lectures/lecture-04.html#ex-3","kind":"example","label":"Ex. 3","title":"Первые примеры многообразий","text":"Первые примеры топологических многообразий: конечные пространства с дискретной топологией — нульмерные многообразия; ℝ и S^1 — одномерные топологические многообразия.","section":"4.2 Топологическое многообразие","source":"Лекция 4"},{"id":"nb-2","url":"lectures/lecture-04.html#nb-2","kind":"nb","label":"NB 2","title":"Выборка — нульмерное многообразие","text":"Конечная выборка различных точек в ℝ^d с индуцированной топологией дискретна и потому является нульмерным многообразием. Положительная «размерность многообразия данных» относится к предполагаемой непрерывной модели, которую приближает выборка.","section":"4.2 Топологическое многообразие","source":"Лекция 4"},{"id":"ex-4","url":"lectures/lecture-04.html#ex-4","kind":"example","label":"Ex. 4","title":"Не многообразия","text":"Примеры пространств, не являющихся топологическими многообразиями: {(x, y) ∈ ℝ^2 mid xy = 0} — нарушена локальная евклидовость в точке (0,0); S^1 vee S^1 («восьмёрка») не является локально евклидовым пространством; ℝ × {0} и ℝ × {1} — два экземпляра прямой, склеенных отождествлением (t, 0) sim (t, 1) ∀ t < 0. Данное…","section":"4.2 Топологическое многообразие","source":"Лекция 4"},{"id":"lm-5","url":"lectures/lecture-04.html#lm-5","kind":"lemma","label":"Lm. 5","title":"Произведение многообразий","text":"Произведение n-мерного многообразия X и m-мерного многообразия Y с топологией произведения является (n+m)-мерным многообразием.","section":"4.2 Топологическое многообразие","source":"Лекция 4"},{"id":"ex-5","url":"lectures/lecture-04.html#ex-5","kind":"example","label":"Ex. 5","title":"Торы и сферы","text":"Ещё примеры топологических многообразий: T^n = S^1 × S^1 × … × S^1 — тор — n-мерное топологическое многообразие; S^n-1 = {x ∈ ℝ^n: \\|x\\| = 1} — (n-1)-мерное топологическое многообразие.","section":"4.2 Топологическое многообразие","source":"Лекция 4"},{"id":"def-8","url":"lectures/lecture-04.html#def-8","kind":"def","label":"Def. 8","title":"Подмногообразие","text":"Подмножество S n-мерного многообразия X называется подмногообразием размерности m < n, если S само является топологическим многообразием размерности m.","section":"4.2 Топологическое многообразие","source":"Лекция 4"},{"id":"ex-6","url":"lectures/lecture-04.html#ex-6","kind":"example","label":"Ex. 6","title":"Примеры подмногообразий","text":"Примеры подмногообразий (всюду m < n): ℝ^m ⩽ ℝ^n, S^m ⩽ S^n, T^m ⩽ T^n.","section":"4.2 Топологическое многообразие","source":"Лекция 4"},{"id":"ml-manifold","url":"lectures/lecture-04.html#ml-manifold","kind":"ml","label":"ИИ","title":"Гипотеза многообразия и узкое горлышко автоэнкодера","text":"Гипотеза многообразия: данные высокой размерности (картинки 256 × 256 × 3) на самом деле лежат около многообразия гораздо меньшей размерности. NB 2 уточняет формулировку: сама выборка — нульмерное многообразие, а «размерность данных» — свойство непрерывной модели, к которой мы выборку приближаем. Теорема Брауэра и а…","section":"4.2 Топологическое многообразие","source":"Лекция 4"},{"id":"def-1","url":"lectures/lecture-05.html#def-1","kind":"def","label":"Def. 1","title":"Карта","text":"Картой на множестве M называется пара (U, varphi), состоящая из подмножества U ⊆ M и биективного отображения varphi: U → O, действующего в открытое (в стандартной топологии) подмножество O ⊆ ℝ^n.","section":"5.1 Карты и атласы","source":"Лекция 5"},{"id":"nb-1","url":"lectures/lecture-05.html#nb-1","kind":"nb","label":"NB 1","title":"Носитель и локальные координаты","text":"Обычно множество U называют носителем карты, а отображение varphi — картирующим отображением. Это отображение представляет собой набор координатных функций на U varphi = (x^1, x^2, …, x^n), x^i: U → ℝ, так что для любой точки P ∈ U мы имеем набор её локальных координат: varphi(P) = (x^1_P, x^2_P, …, x^n_P), x^i_P = …","section":"5.1 Карты и атласы","source":"Лекция 5"},{"id":"def-2","url":"lectures/lecture-05.html#def-2","kind":"def","label":"Def. 2","title":"Центрированная карта","text":"Говорят, что карта (U, varphi) центрирована в точке P ∈ U, если varphi(P) = 0.","section":"5.1 Карты и атласы","source":"Лекция 5"},{"id":"def-3","url":"lectures/lecture-05.html#def-3","kind":"def","label":"Def. 3","title":"Согласованные карты","text":"Две карты (U, varphi) и (V, psi) называются C^r-согласованными в одном из двух случаев: U ∩ V = ∅; U ∩ V = W ≠ ∅, и тогда varphi(W) и psi(W) — открытые в ℝ^n множества; psi circ varphi^-1: varphi(W) → psi(W) — C^r- диффеоморфизм.","section":"5.1 Карты и атласы","source":"Лекция 5"},{"id":"nb-2","url":"lectures/lecture-05.html#nb-2","kind":"nb","label":"NB 2","title":"Замена координат","text":"Говорят, что отображение chi = psi circ varphi^-1 осуществляет замену координат на W: beginaligned varphi &= (x^1, x^2, …, x^n), psi = (y^1, y^2, …, y^n) \\\\ chi &= psi circ varphi^-1: y^i = y^i(x^1, x^2, …, x^n). endaligned","section":"5.1 Карты и атласы","source":"Лекция 5"},{"id":"def-4","url":"lectures/lecture-05.html#def-4","kind":"def","label":"Def. 4","title":"Атлас","text":"C^r-атласом на M называется множество mathcalA_M = {(U_α, varphi_α)}_α попарно согласованных карт, чьи носители {U_α} образуют покрытие множества M.","section":"5.1 Карты и атласы","source":"Лекция 5"},{"id":"ex-1","url":"lectures/lecture-05.html#ex-1","kind":"example","label":"Ex. 1","title":"Первые примеры атласов","text":"Первые примеры атласов на множествах: M = ℝ, mathcalA_M = {(ℝ, id)}; M = S^1 = {(x, y) ∈ ℝ^2: \\ x^2 + y^2 = 1}, mathcalA_M = {(U, varphi), (V, psi)}: beginaligned U &= S^1 \\ {(0,1)}, & varphi(x, y) &= x/(1 - y) = α, \\\\ V &= S^1 \\ {(0,-1)}, & psi(x, y) &= x/(1 + y) = beta, \\\\ U ∩ V &= S^1 \\ {(0,1), (0,-1)}, & & \\\\ be…","section":"5.1 Карты и атласы","source":"Лекция 5"},{"id":"ml-charts","url":"lectures/lecture-05.html#ml-charts","kind":"ml","label":"ИИ","title":"Карта как латентные координаты","text":"Энкодер — это карта. Когда автоэнкодер сжимает картинку в латентный вектор z ∈ ℝ^d, он по сути строит varphi: U → O ⊆ ℝ^d на куске «многообразия данных», а декодер играет роль varphi^-1. Требование биективности — это ровно идеальная реконструкция: varphi^-1(varphi(P)) = P. Замена координат — репараметризация. Две ра…","section":"5.1 Карты и атласы","source":"Лекция 5"},{"id":"def-5","url":"lectures/lecture-05.html#def-5","kind":"def","label":"Def. 5","title":"Карта, согласованная с атласом","text":"Карта (U, varphi) называется C^r-согласованной с атласом mathcalA_M, если объединение mathcalA_M ∪ {(U, varphi)} — снова C^r-атлас на M.","section":"5.2 Дифференциальная структура","source":"Лекция 5"},{"id":"lm-1","url":"lectures/lecture-05.html#lm-1","kind":"lemma","label":"Lm. 1","title":"Все согласованные карты образуют атлас","text":"Множество widetildemathcalA_M всех карт, C^r-согласованных с mathcalA_M, является C^r-атласом.","section":"5.2 Дифференциальная структура","source":"Лекция 5"},{"id":"def-6","url":"lectures/lecture-05.html#def-6","kind":"def","label":"Def. 6","title":"Эквивалентные атласы","text":"Атласы mathcalA_M и mathcalA'_M называются эквивалентными, если mathcalA_M ∪ mathcalA'_M — снова атлас на M.","section":"5.2 Дифференциальная структура","source":"Лекция 5"},{"id":"def-7","url":"lectures/lecture-05.html#def-7","kind":"def","label":"Def. 7","title":"Максимальный атлас (структура)","text":"Максимальным C^r-атласом или C^r-структурой на M называется максимальный по включению элемент в классе эквивалентных атласов.","section":"5.2 Дифференциальная структура","source":"Лекция 5"},{"id":"def-8","url":"lectures/lecture-05.html#def-8","kind":"def","label":"Def. 8","title":"Дифференцируемое многообразие","text":"Пара ⟨M, widetildemathcalA_M⟩ называется C^r-дифференцируемым многообразием. Требования хаусдорфовости и паракомпактности индуцированной топологии будут добавлены в следующей лекции.","section":"5.2 Дифференциальная структура","source":"Лекция 5"},{"id":"ex-2","url":"lectures/lecture-05.html#ex-2","kind":"example","label":"Ex. 2","title":"Различные структуры на прямой","text":"Пусть M = ℝ и r ⩾ 1. Для каждого α > 0 рассмотрим отображение varphi_α: ℝ → ℝ varphi_α(x) = begincases x, & x ⩽ 0, \\\\ α x, & x > 0, endcases (varphi_α circ varphi_beta^-1)(x) = begincases x, & x ⩽ 0, \\\\ (α/beta) x, & x > 0. endcases Атласы {(ℝ, varphi_α)} при α > 0 порождают попарно различные C^r-структуры на ℝ: есл…","section":"5.2 Дифференциальная структура","source":"Лекция 5"},{"id":"nb-3","url":"lectures/lecture-05.html#nb-3","kind":"nb","label":"NB 3","title":"Размерность и класс гладкости","text":"Число n называется размерностью многообразия M. Многообразие имеет класс гладкости C^r, если все переходы psi circ varphi^-1 между картами его атласа являются диффеоморфизмами класса C^r. Значение r = ∞ отвечает гладким многообразиям. При r = 0 под C^0-диффеоморфизмами понимаются гомеоморфизмы; после добавления указ…","section":"5.2 Дифференциальная структура","source":"Лекция 5"},{"id":"ex-3","url":"lectures/lecture-05.html#ex-3","kind":"example","label":"Ex. 3","title":"Атласы окружности","text":"M = S^1: \\ x^2 + y^2 = 1 — окружность. Пусть P_0 = (1, 0) и Q_0 = (-1, 0). Атлас на S^1 могут составить две карты: beginaligned U &= S^1 \\ {P_0}, & &varphi(P) — угол, отсчитываемый от точки Q_0, \\\\ V &= S^1 \\ {Q_0}, & &psi(P) — угол, отсчитываемый от точки P_0. endaligned Оба угла отсчитываются против часовой стрелк…","section":"5.2 Дифференциальная структура","source":"Лекция 5"},{"id":"ml-structure","url":"lectures/lecture-05.html#ml-structure","kind":"ml","label":"ИИ","title":"Атлас как смесь карт в manifold learning","text":"Mixture of charts. Одна карта часто не может покрыть многообразие данных — как одна карта не покрывает окружность. Поэтому в manifold learning есть модели «атлас из нескольких энкодеров»: каждая компонента смеси отвечает за свой кусок данных и даёт локальные координаты, а гейтинг выбирает карту. Требование согласова…","section":"5.2 Дифференциальная структура","source":"Лекция 5"},{"id":"def-9","url":"lectures/lecture-05.html#def-9","kind":"def","label":"Def. 9","title":"Декартово произведение многообразий","text":"Декартовым произведением многообразий ⟨M, mathcalA_M⟩ и ⟨N, mathcalA_N⟩ называется пара ⟨X, mathcalA_X⟩: X = M × N, mathcalA_X = widetildemathcalB_X, где widetildemathcalB_X — максимальный атлас, порождённый атласом произведений карт mathcalB_X = {(U × V, varphi × psi) mid (U, varphi) ∈ mathcalA_M,\\ (V, psi) ∈ mathc…","section":"5.3 Декартово произведение","source":"Лекция 5"},{"id":"lm-2","url":"lectures/lecture-05.html#lm-2","kind":"lemma","label":"Lm. 2","title":"Произведение — многообразие","text":"⟨X, mathcalA_X⟩ — C^r-дифференцируемое многообразие размерности n + m.","section":"5.3 Декартово произведение","source":"Лекция 5"},{"id":"ex-4","url":"lectures/lecture-05.html#ex-4","kind":"example","label":"Ex. 4","title":"Новые примеры многообразий","text":"Новые примеры многообразий: ℝ^2 = ℝ × ℝ — плоскость; C = ℝ × S^1 — цилиндр; T^2 = S^1 × S^1 — тор.","section":"5.3 Декартово произведение","source":"Лекция 5"},{"id":"ml-product","url":"lectures/lecture-05.html#ml-product","kind":"ml","label":"ИИ","title":"Произведение и факторизованные представления","text":"Факторизованные (disentangled) представления. Мечта beta-VAE и родственных моделей — латентное пространство как произведение: одна группа координат отвечает за форму объекта, другая — за поворот, третья — за цвет. Геометрически это ровно карта-произведение varphi × psi: координаты разных факторов не смешиваются, и з…","section":"5.3 Декартово произведение","source":"Лекция 5"},{"id":"nb-1","url":"lectures/lecture-06.html#nb-1","kind":"nb","label":"NB 1","title":"Образ объединения и пересечения","text":"Пусть ⟨M, widetildemathcalA_M⟩ — дифференцируемое n-мерное многообразие и {O_beta} — некоторое семейство подмножеств M. Тогда для любой карты (U, varphi) ∈ widetildemathcalA_M имеют место следующие свойства: ⋃_beta varphi(O_beta ∩ U) = varphi((⋃_beta O_beta) ∩ U), ⋂_beta varphi(O_beta ∩ U) = varphi((⋂_beta O_beta) ∩…","section":"6.1 Открытые множества","source":"Лекция 6"},{"id":"def-1","url":"lectures/lecture-06.html#def-1","kind":"def","label":"Def. 1","title":"Открытое множество многообразия","text":"Подмножество O ⊂ M называется открытым в M, если для любой карты (U, varphi) ∈ widetildemathcalA_M образ varphi(O ∩ U) открыт в ℝ^n.","section":"6.1 Открытые множества","source":"Лекция 6"},{"id":"nb-2","url":"lectures/lecture-06.html#nb-2","kind":"nb","label":"NB 2","title":"Многообразие — топологическое пространство","text":"Таким образом, каждое многообразие является топологическим пространством с топологией τ, индуцированной дифференциальной структурой widetildemathcalA_M на M.","section":"6.1 Открытые множества","source":"Лекция 6"},{"id":"lm-1","url":"lectures/lecture-06.html#lm-1","kind":"lemma","label":"Lm. 1","title":"Достаточно покрывающих карт","text":"Пусть O ⊂ M и {(U_beta, varphi_beta)} — набор карт, согласованных с максимальным атласом widetildemathcalA_M и таких, что O ⊆ ⋃_beta U_beta. Тогда O открыто в M, если и только если открыты в ℝ^n все множества varphi_beta(O ∩ U_beta).","section":"6.1 Открытые множества","source":"Лекция 6"},{"id":"nb-3","url":"lectures/lecture-06.html#nb-3","kind":"nb","label":"NB 3","title":"Область карты открыта","text":"Для любой карты (U, varphi) ∈ widetildemathcalA_M произвольное подмножество V ⊂ U будет открытым в M, если varphi(V) является открытым в ℝ^n. В частности, открытым в M является множество U.","section":"6.1 Открытые множества","source":"Лекция 6"},{"id":"def-2","url":"lectures/lecture-06.html#def-2","kind":"def","label":"Def. 2","title":"Открытое подмногообразие","text":"Открытым подмногообразием многообразия M называется открытое подмножество S ⊂ M с дифференциальной структурой widetildemathcalA_S = {(S ∩ U_α, varphi_α|_S ∩ U_α)}_α, если widetildemathcalA_M = {(U_α, varphi_α)}.","section":"6.1 Открытые множества","source":"Лекция 6"},{"id":"nb-4","url":"lectures/lecture-06.html#nb-4","kind":"nb","label":"NB 4","title":"Обозначение и размерность","text":"Тот факт, что S является открытым подмногообразием M, будем записывать S ⩽ M. dim S = dim M = n. (1)","section":"6.1 Открытые множества","source":"Лекция 6"},{"id":"ml-chart-autoencoder","url":"lectures/lecture-06.html#ml-chart-autoencoder","kind":"ml","label":"ИИ","title":"Атлас из энкодеров","text":"Одной карты часто не хватает. Обычный автоэнкодер — это попытка покрыть многообразие данных одной картой: энкодер varphi переводит данные в открытое множество ℝ^n. Для окружности или сферы так нельзя: компактное S^1 не гомеоморфно открытому подмножеству ℝ. Поэтому существуют «атласные» автоэнкодеры (chart autoencode…","section":"6.1 Открытые множества","source":"Лекция 6"},{"id":"lm-2","url":"lectures/lecture-06.html#lm-2","kind":"lemma","label":"Lm. 2","title":"Первая аксиома счётности","text":"Топология τ_M удовлетворяет первой аксиоме счётности.","section":"6.2 Свойства индуцированной топологии","source":"Лекция 6"},{"id":"ex-1","url":"lectures/lecture-06.html#ex-1","kind":"example","label":"Ex. 1","title":"Несчётное дискретное многообразие","text":"Примером многообразия, топология которого не удовлетворяет второй аксиоме счётности, является дизъюнктное объединение несчётного числа одноточечных множеств. Более конкретно, рассмотрим M = ℝ как дискретное многообразие размерности нуль. Каждая точка P ∈ M имеет в этом случае единственную координатную окрестность O_…","section":"6.2 Свойства индуцированной топологии","source":"Лекция 6"},{"id":"def-3","url":"lectures/lecture-06.html#def-3","kind":"def","label":"Def. 3","title":"Дифференцируемое многообразие","text":"Дифференцируемым n-мерным многообразием класса C^r называется множество M с заданной на нём дифференциальной структурой widetildemathcalA_M, индуцирующей топологию паракомпактного хаусдорфова пространства.","section":"6.2 Свойства индуцированной топологии","source":"Лекция 6"},{"id":"ex-2","url":"lectures/lecture-06.html#ex-2","kind":"example","label":"Ex. 2","title":"Прямая с двумя нулями","text":"Пусть a, b и c — три непересекающиеся копии прямой. Рассмотрим множество M = U ∪ V с картами U = {(x,a): x ⩽ 0} ∪ {(x,b): x > 0}, varphi(x,α) = x, α ∈ {a,b}, V = {(x,c): x ⩽ 0} ∪ {(x,b): x > 0}, psi(x,beta) = x, beta ∈ {b,c}. Образы обеих карт равны ℝ, а переход тождествен на (0,∞). Любые окрестности точек (0,a) и (…","section":"6.2 Свойства индуцированной топологии","source":"Лекция 6"},{"id":"th-6-1","url":"lectures/lecture-06.html#th-6-1","kind":"theorem","label":"Th. 6.1","title":"Когда топология совпадает с индуцированной","text":"Пусть ⟨M, widetildemathcalA_M⟩ и ⟨M, τ⟩ — дифференциальная и топологическая структуры на множестве M. Топология τ_M, индуцированная атласом widetildemathcalA_M, будет совпадать с данной топологией τ тогда и только тогда, когда для каждой карты (U, varphi) ∈ widetildemathcalA_M множество U будет открыто в τ, а отобра…","section":"6.2 Свойства индуцированной топологии","source":"Лекция 6"},{"id":"ml-first-countable","url":"lectures/lecture-06.html#ml-first-countable","kind":"ml","label":"ИИ","title":"Последовательностей достаточно","text":"Почему в ML можно думать последовательностями. Lm. 2 означает, что на любом многообразии — пространстве параметров, сфере нормированных эмбеддингов, многообразии ортогональных матриц — непрерывность и замыкание можно проверять через сходящиеся последовательности (как в лекции 2). «Шаг оптимизатора → 0, итерации сход…","section":"6.2 Свойства индуцированной топологии","source":"Лекция 6"},{"id":"def-4","url":"lectures/lecture-06.html#def-4","kind":"def","label":"Def. 4","title":"Вложенное подмногообразие","text":"Подмножество M ⊂ mathcalE называется вложенным подмногообразием класса C^r размерности 0 ⩽ n ⩽ d, если для каждой точки x ∈ M существует открытая окрестность O_x ⊂ mathcalE, открытое множество V_x ⊂ ℝ^d и C^r-диффеоморфизм varphi_x: O_x → V_x, такие что varphi_x(M ∩ O_x) = V_x ∩ E, E = ℝ^n × {0}^d-n.","section":"6.3 Многообразия в евклидовом пространстве","source":"Лекция 6"},{"id":"lm-3","url":"lectures/lecture-06.html#lm-3","kind":"lemma","label":"Lm. 3","title":"Структура на вложенном подмногообразии","text":"Вложенное подмногообразие M обладает естественной дифференциальной структурой класса C^r, индуцирующей топологию подпространства.","section":"6.3 Многообразия в евклидовом пространстве","source":"Лекция 6"},{"id":"ex-3","url":"lectures/lecture-06.html#ex-3","kind":"example","label":"Ex. 3","title":"Множество решений линейной системы","text":"Пусть A ∈ ℝ^d × d — матрица такая, что rank A = k, и фиксирован b ∈ Im A. Тогда следующее множество является гладким многообразием размерности dim M = d - k: M = {x ∈ ℝ^d: \\ Ax = b}.","section":"6.3 Многообразия в евклидовом пространстве","source":"Лекция 6"},{"id":"th-6-2","url":"lectures/lecture-06.html#th-6-2","kind":"theorem","label":"Th. 6.2","title":"Критерий через локально определяющую функцию","text":"Непустое подмножество M евклидова пространства mathcalE является вложенным подмногообразием класса C^r размерности n < d тогда и только тогда, когда для каждой точки x ∈ M существует открытая окрестность U_x ⊂ mathcalE и C^r-гладкая функция h: U_x → ℝ^d-n, такая, что: U_x ∩ M = {y ∈ U_x: \\ h(y) = 0} = h^-1(0); rank …","section":"6.3 Многообразия в евклидовом пространстве","source":"Лекция 6"},{"id":"nb-5","url":"lectures/lecture-06.html#nb-5","kind":"nb","label":"NB 5","title":"Локально определяющая функция","text":"Функция h: U_x → ℝ^d-n из теоремы называется локально определяющей.","section":"6.3 Многообразия в евклидовом пространстве","source":"Лекция 6"},{"id":"ex-4","url":"lectures/lecture-06.html#ex-4","kind":"example","label":"Ex. 4","title":"Не локально определяющие функции","text":"Примеры C^r-гладких функций, не являющихся локально определяющими в начале координат: h(x_1, x_2) = x_1^2 - x_2^2 — крест; h(x_1, x_2) = x_1^2 - x_2^3 — точка возврата; h(x_1, x_2) = x_1^2 - x_2^4 — двойная парабола.","section":"6.3 Многообразия в евклидовом пространстве","source":"Лекция 6"},{"id":"ex-5","url":"lectures/lecture-06.html#ex-5","kind":"example","label":"Ex. 5","title":"Окружность","text":"Примером C^r-гладкой локально определяющей функции окружности S^1 является h(x_1, x_2) = x_1^2 + x_2^2 - 1.","section":"6.3 Многообразия в евклидовом пространстве","source":"Лекция 6"},{"id":"ml-manifold-constraints","url":"lectures/lecture-06.html#ml-manifold-constraints","kind":"ml","label":"ИИ","title":"Гипотеза многообразия и ограничения","text":"Гипотеза многообразия на языке Def. 4. «Данные лежат на n-мерном многообразии в ℝ^d» — это ровно существование локальных выпрямлений: около каждой точки данных есть гладкая замена координат, в которой данные занимают n координат, а остальные d - n — «шум». Th. 6.2 говорит то же через d - n независимых ограничений на…","section":"6.3 Многообразия в евклидовом пространстве","source":"Лекция 6"},{"id":"ml-licq","url":"lectures/lecture-06.html#ml-licq","kind":"ml","label":"ИИ","title":"Независимость градиентов и метод Лагранжа","text":"Условие 2 Th. 6.2 — это LICQ. Задача min f(x) при h(x) = 0 решается методом Лагранжа: в минимуме nabla f = Σ_i lambda_i nabla h_i. Теорема о множителях требует linear independence constraint qualification — линейной независимости nabla h_i(x^*), то есть rank Dh(x^*) = число ограничений. Это ровно регулярность уровня…","section":"6.3 Многообразия в евклидовом пространстве","source":"Лекция 6"},{"id":"ml-flows-jacobian","url":"lectures/lecture-06.html#ml-flows-jacobian","kind":"ml","label":"ИИ","title":"Ранг якобиана в нормализующих потоках","text":"Матрица Dvarphi из доказательства — это coupling-слой. В RealNVP слой y_1:n = x_1:n, y_n+1:d = x_n+1:d odot e^s(x_1:n) + t(x_1:n) имеет якобиан beginbmatrix I_n & 0 \\\\ A & B endbmatrix с диагональным B = diag(e^s) — ровно блочная структура Dvarphi(x). Определитель det B = prod e^s_i считается за линейное время, и он…","section":"6.3 Многообразия в евклидовом пространстве","source":"Лекция 6"},{"id":"def-1","url":"lectures/lecture-07.html#def-1","kind":"def","label":"Def. 1","title":"Дифференцируемость в точке","text":"Отображение sigma: M → N называется C^r-дифференцируемым в точке P ∈ M, если найдутся карты (U, varphi) ∈ widetildemathcalA_M и (V, psi) ∈ widetildemathcalA_N, такие, что P ∈ U, sigma(U) ⊂ V, и следующее отображение является C^r-дифференцируемым: widehatsigma = psi circ sigma circ varphi^-1: varphi(U) → psi(V).","section":"3.1 Дифференцируемые отображения","source":"Лекция 7"},{"id":"nb-1","url":"lectures/lecture-07.html#nb-1","kind":"nb","label":"NB 1","title":"Дифференцируемость на M, координатный представитель","text":"Отображение sigma: M → N, C^r-дифференцируемое в каждой точке P ∈ M, называется C^r-дифференцируемым на M. Отображение widehatsigma называется координатным представителем отображения sigma в картах (U, varphi) и (V, psi).","section":"3.1 Дифференцируемые отображения","source":"Лекция 7"},{"id":"lm-1","url":"lectures/lecture-07.html#lm-1","kind":"lemma","label":"Lm. 1","title":"Независимость от выбора карт","text":"Свойство C^r-дифференцируемости отображения sigma: M → N в точке P не зависит от выбора карт (U, varphi) ∈ widetildemathcalA_M и (V, psi) ∈ widetildemathcalA_N, содержащих P ∈ M и sigma(P) ∈ N соответственно, после сужения карт к окрестностям этих точек.","section":"3.1 Дифференцируемые отображения","source":"Лекция 7"},{"id":"def-2","url":"lectures/lecture-07.html#def-2","kind":"def","label":"Def. 2","title":"Дифференцируемость на подмножестве","text":"Пусть M и N — дифференцируемые C^r-многообразия и S ⊂ M — произвольное подмножество M. Отображение sigma: S → N называется C^r-дифференцируемым на S, если для каждой точки P ∈ S: существует открытая окрестность O_P ⊂ M, содержащая точку P; существует C^r-отображение widetildesigma: O_P → N, такое, что widetildesigma…","section":"3.1 Дифференцируемые отображения","source":"Лекция 7"},{"id":"def-3","url":"lectures/lecture-07.html#def-3","kind":"def","label":"Def. 3","title":"Диффеоморфизм","text":"Гомеоморфизм sigma: M → N, обладающий тем свойством, что sigma и sigma^-1 являются C^r-дифференцируемыми отображениями, называется C^r-диффеоморфизмом. В этом случае многообразия называются диффеоморфными.","section":"3.1 Дифференцируемые отображения","source":"Лекция 7"},{"id":"ex-1","url":"lectures/lecture-07.html#ex-1","kind":"example","label":"Ex. 1","title":"Диск диффеоморфен плоскости","text":"Отображение sigma: D^2 → ℝ^2 двумерного диска D^2 = {(x,y) ∈ ℝ^2: x^2 + y^2 < 1} на плоскость ℝ^2, задаваемое функциями (x, y) mapsto (x/z,\\ y/z), z = √(1 - x^2 - y^2), является диффеоморфизмом.","section":"3.1 Дифференцируемые отображения","source":"Лекция 7"},{"id":"ex-2","url":"lectures/lecture-07.html#ex-2","kind":"example","label":"Ex. 2","title":"Гладкий гомеоморфизм, не диффеоморфизм","text":"Отображение sigma: ℝ → ℝ, заданное формулой x mapsto x^3, является гладким гомеоморфизмом стандартной прямой, но не C^r-диффеоморфизмом при r ⩾ 1: обратное отображение y mapsto sqrt[3]y не дифференцируемо в нуле.","section":"3.1 Дифференцируемые отображения","source":"Лекция 7"},{"id":"ml-diffeo-flows","url":"lectures/lecture-07.html#ml-diffeo-flows","kind":"ml","label":"ИИ","title":"Диффеоморфизмы и нормализующие потоки","text":"Нормализующий поток — это диффеоморфизм. Поток f_theta: ℝ^d → ℝ^d переводит гауссовский шум z в данные x = f_theta(z), а плотность считается по формуле замены переменных: log p_X(x) = log p_Zbigl(f_theta^-1(x)bigr) + log bigl|det D f_theta^-1(x)bigr|. Здесь нужны обе стороны: f_theta^-1 — чтобы считать правдоподобие…","section":"3.1 Дифференцируемые отображения","source":"Лекция 7"},{"id":"def-4","url":"lectures/lecture-07.html#def-4","kind":"def","label":"Def. 4","title":"Кривая на многообразии","text":"Кривой или путём на многообразии M называется непрерывное отображение gamma: I → M, где I ⊂ ℝ — интервал. Кривая называется C^r-дифференцируемой, если gamma имеет класс C^r в смысле определения гладкости на подмножестве, и гладкой при r = ∞.","section":"3.2 Гладкие кривые и функции","source":"Лекция 7"},{"id":"nb-2","url":"lectures/lecture-07.html#nb-2","kind":"nb","label":"NB 2","title":"Представитель кривой","text":"Представителем кривой gamma в произвольной карте (U, varphi) является параметрически заданная кривая widehatgamma = varphi circ gamma: gamma^-1(U) → varphi(U) в координатном пространстве ℝ^n: widehatgamma(t) = bigl(x^1(t), x^2(t), …, x^n(t)bigr).","section":"3.2 Гладкие кривые и функции","source":"Лекция 7"},{"id":"ex-3","url":"lectures/lecture-07.html#ex-3","kind":"example","label":"Ex. 3","title":"Кривая на сфере","text":"На двумерной сфере S^2 = {(x, y, z): x^2 + y^2 + z^2 = 1} кривую можно задать, используя либо внутренние координаты (theta, psi), либо прямоугольные декартовы координаты (x, y, z). В первом случае в области угловой карты имеем widehatgamma(t) = (theta(t), psi(t)), а во втором P(t) = (x(t), y(t), z(t)), P(t) ∈ S^2.","section":"3.2 Гладкие кривые и функции","source":"Лекция 7"},{"id":"def-5","url":"lectures/lecture-07.html#def-5","kind":"def","label":"Def. 5","title":"Функция на многообразии","text":"Функцией на многообразии M называется отображение f: M → ℝ, сопоставляющее каждой точке P ∈ M вещественное число a ∈ ℝ.","section":"3.2 Гладкие кривые и функции","source":"Лекция 7"},{"id":"nb-3","url":"lectures/lecture-07.html#nb-3","kind":"nb","label":"NB 3","title":"Представитель функции","text":"Представителем функции f в произвольной карте (U, varphi) ∈ widetildemathcalA_M будет функция widehatf = f circ varphi^-1: varphi(U) → ℝ от нескольких переменных: f(P) = widehatfbigl(x^1_P, x^2_P, …, x^n_Pbigr).","section":"3.2 Гладкие кривые и функции","source":"Лекция 7"},{"id":"ml-curves-functions","url":"lectures/lecture-07.html#ml-curves-functions","kind":"ml","label":"ИИ","title":"Кривые в латентном пространстве и функции потерь на многообразиях","text":"Интерполяция в латентном пространстве — это выбор кривой. Если латенты нормированы (лежат на сфере, как эмбеддинги после L2-нормировки), прямая z(t) = (1-t)z_0 + tz_1 выходит со сферы внутрь шара — в область, которую модель никогда не видела. Сферическая интерполяция (slerp) — кривая на S^d-1, в угловых координатах …","section":"3.2 Гладкие кривые и функции","source":"Лекция 7"},{"id":"nb-4","url":"lectures/lecture-07.html#nb-4","kind":"nb","label":"NB 4","title":"Носитель функции","text":"Напомним, что носителем supp(f) функции f: X → ℝ, заданной на топологическом пространстве X, называется замыкание подмножества, на котором функция f принимает значения, отличные от нуля.","section":"3.3 Разбиение единицы","source":"Лекция 7"},{"id":"lm-2","url":"lectures/lecture-07.html#lm-2","kind":"lemma","label":"Lm. 2","title":"Существование срезающей функции","text":"Пусть K — компактное подмножество гладкого многообразия M и O — открытое в M подмножество, содержащее K. Тогда существует гладкая функция beta: M → ℝ, которая равна 1 на K, принимает значения из отрезка [0, 1] и имеет компактный носитель supp(beta) в O.","section":"3.3 Разбиение единицы","source":"Лекция 7"},{"id":"def-6","url":"lectures/lecture-07.html#def-6","kind":"def","label":"Def. 6","title":"Срезающая функция","text":"Функция beta: M → ℝ, обладающая перечисленными в лемме свойствами, называется срезающей функцией.","section":"3.3 Разбиение единицы","source":"Лекция 7"},{"id":"nb-5","url":"lectures/lecture-07.html#nb-5","kind":"nb","label":"NB 5","title":"Продолжение нулём","text":"Пусть f: U → ℝ — гладкая функция, заданная на U ⊂ M и beta — срезающая функция, такая что supp(beta) ⊂ U. Тогда beta cdot f, продолженная нулём вне U, — гладкая функция, определённая на всём M и принимающая значение 0 вне U.","section":"3.3 Разбиение единицы","source":"Лекция 7"},{"id":"ml-smooth-gates","url":"lectures/lecture-07.html#ml-smooth-gates","kind":"ml","label":"ИИ","title":"Гладкие выключатели: smoothstep, гейтинг, оконные функции","text":"Жёсткий порог не обучается. Индикатор 1[x > 0] имеет нулевую производную почти всюду — градиентный спуск через него ничего не узнаёт. Поэтому в нейросетях всюду стоят гладкие ступеньки: сигмоида в LSTM/GRU-гейтах, x sigma(x) в SiLU/GELU, smoothstep 3t^2 - 2t^3 в графике и в neural fields. Они дифференцируемы, но — в…","section":"3.3 Разбиение единицы","source":"Лекция 7"},{"id":"def-7","url":"lectures/lecture-07.html#def-7","kind":"def","label":"Def. 7","title":"Разбиение единицы","text":"Разбиением единицы на гладком многообразии M называется семейство {varphi_α}_α ∈ A гладких функций на M, удовлетворяющих следующим условиям: 0 ⩽ varphi_α ⩽ 1, ∀ α ∈ A; для каждой точки P ∈ M существует открытая окрестность W_P ni P, такая, что W_P ∩ supp(varphi_α) = ∅ для всех, кроме конечного числа, индексов α; ∀ P…","section":"3.3 Разбиение единицы","source":"Лекция 7"},{"id":"def-8","url":"lectures/lecture-07.html#def-8","kind":"def","label":"Def. 8","title":"Подчинённое разбиение единицы","text":"Говорят, что разбиение единицы {varphi_α}_α ∈ A подчинено открытому покрытию mathcalO_M = {O_α}_α ∈ A многообразия M, если для всех α ∈ A имеет место supp(varphi_α) ⊂ O_α.","section":"3.3 Разбиение единицы","source":"Лекция 7"},{"id":"th-3-1","url":"lectures/lecture-07.html#th-3-1","kind":"theorem","label":"Th. 3.1","title":"Существование разбиения единицы","text":"Пусть M — гладкое многообразие и mathcalO_M = {O_α}_α ∈ A — произвольное открытое покрытие M. Тогда существует разбиение единицы {varphi_α}_α ∈ A, подчинённое этому покрытию.","section":"3.3 Разбиение единицы","source":"Лекция 7"},{"id":"ml-moe-partition","url":"lectures/lecture-07.html#ml-moe-partition","kind":"ml","label":"ИИ","title":"Разбиение единицы и softmax-гейтинг","text":"Mixture of Experts — разбиение единицы на пространстве входов. Гейтинг g(x) = softmax(Wx) даёт веса g_i(x) ∈ [0,1] с Σ_i g_i(x) = 1 — условия 1 и 3 из Def. 7. Модель y = Σ_i g_i(x) f_i(x) — та самая склейка локальных «экспертов» взвешенной суммой. Нормировка softmax e^a_i / Σ_j e^a_j — ровно шаг 3 наброска: положите…","section":"3.3 Разбиение единицы","source":"Лекция 7"},{"id":"ml-fem-rbf","url":"lectures/lecture-07.html#ml-fem-rbf","kind":"ml","label":"ИИ","title":"Сплайны, конечные элементы и RBF","text":"Конечные элементы. «Шапочки» кусочно-линейных базисных функций на сетке неотрицательны, имеют компактный носитель (соседние ячейки) и дают в сумме 1 — разбиение единицы (лишь непрерывное, не гладкое). B-сплайны степени k — тоже разбиение единицы, уже класса C^k-1; на этом стоят KAN-сети (Kolmogorov–Arnold Networks),…","section":"3.3 Разбиение единицы","source":"Лекция 7"},{"id":"bilet-1","url":"pract/kolok-01.html#bilet-1","kind":"ticket","label":"Билет 1","title":"Аксиомы топологии. Сравнение топологий на одном множестве","text":"По конспекту: Def. 1, Def. 2, Ex. 1–5, Def. 4, NB 2 лекции 1; задача 1 листка 1. План ответа на минуту: Def. 1: три аксиомы; подчеркнуть «любого» в аксиоме 2 и «конечного» в аксиоме 3. Почему конечность: ⋂_n (-tfrac1n, tfrac1n) = {0} не открыто в τ_st. Def. 2: пространство — пара ⟨X, τ⟩; «открыто» имеет смысл только…","section":"Билет 1. Аксиомы топологии. Сравнение топологий на одном множестве","source":"Коллоквиум, часть 1"},{"id":"bilet-2","url":"pract/kolok-01.html#bilet-2","kind":"ticket","label":"Билет 2","title":"Индуцированная топология на подмножестве. Относительная открытость","text":"По конспекту: Def. 3, Ex. 6, NB 1, Lm. 1 лекции 1; задачи 5, 6 листка 1. План ответа на минуту: Def. 3: τ_S = {S ∩ T_α}, T_α ∈ τ_X — следы открытых множеств. Проверка, что τ_S — топология (три аксиомы через следы). Ex. 6: [0,1) в стрелке, τ_S = {∅, S} ∪ {(a,1)}. NB 1: (-1,1)×{0} открыто в S = ℝ×{0}, но не в ℝ^2. Lm.…","section":"Билет 2. Индуцированная топология на подмножестве. Относительная открытость","source":"Коллоквиум, часть 1"},{"id":"bilet-3","url":"pract/kolok-01.html#bilet-3","kind":"ticket","label":"Билет 3","title":"Топология произведения. База открытых прямоугольников в ℝ²","text":"По конспекту: Lm. 2, Ex. 7, Def. 13, Lm. 6 лекции 1; задача 8 листка 1, задача 2.1.5 листка 2. План ответа на минуту: Lm. 2: τ_X× Y — произвольные объединения прямоугольников A_i × B_i, A_i ∈ τ_X, B_i ∈ τ_Y. Проверка аксиом; ключевой шаг — (A_1× B_1)∩(A_2× B_2) = (A_1∩ A_2)×(B_1∩ B_2). Прямоугольники — база (Lm. 6),…","section":"Билет 3. Топология произведения. База открытых прямоугольников в $\\mathbb{R}^2$","source":"Коллоквиум, часть 1"},{"id":"bilet-4","url":"pract/kolok-01.html#bilet-4","kind":"ticket","label":"Билет 4","title":"Окрестности точки. Внутренние, внешние и граничные точки множества","text":"По конспекту: Def. 5, NB 3, Def. 6–9, Lm. 3, Lm. 4, Ex. 8, Ex. 9, Ex. 10 лекции 1; задача 7. План ответа на минуту: Def. 5: окрестность O_P — открытое множество, содержащее P (в курсе окрестность открыта); NB 3. Def. 6, 8, 9: внутренняя — ∃ O_P ⊆ S; внешняя — ∃ O_P ⊆ S^c; граничная — ∀ O_P задевает и S, и S^c. Def. …","section":"Билет 4. Окрестности точки. Внутренние, внешние и граничные точки множества","source":"Коллоквиум, часть 1"},{"id":"bilet-5","url":"pract/kolok-01.html#bilet-5","kind":"ticket","label":"Билет 5","title":"Замыкание множества, точки прикосновения и связь замыкания с границей","text":"По конспекту: Def. 10, Def. 11, Def. 12, Lm. 5, NB 5, NB 6, Ex. 11 лекции 1; задачи 3, 9 листка 1. План ответа на минуту: Def. 10: замкнутое — дополнение открытого; NB 6: открытое и замкнутое — не антонимы. Def. 11: Cl_X(S) — наименьшее замкнутое, содержащее S; Def. 12: точка прикосновения. Lm. 5: замыкание существу…","section":"Билет 5. Замыкание множества, точки прикосновения и связь замыкания с границей","source":"Коллоквиум, часть 1"},{"id":"bilet-6","url":"pract/kolok-01.html#bilet-6","kind":"ticket","label":"Билет 6","title":"База и предбаза. Условия, при которых семейство множеств служит базой топологии","text":"По конспекту: Def. 13, Lm. 6, Ex. 12, NB 7, Th. 1.1, Def. 14 лекции 1; задачи 2.1.1–2.1.7 листка 2. План ответа на минуту: Def. 13: база — эталонные окрестности, ∀ P\\ ∀ O_P\\ ∃ V ∈ beta: P ∈ V ⊆ O_P. Lm. 6: при beta ⊆ τ база ⟺ каждое открытое — объединение элементов beta. Ex. 12: интервалы с рациональными концами — с…","section":"Билет 6. База и предбаза. Условия, при которых семейство множеств служит базой топологии","source":"Коллоквиум, часть 1"},{"id":"bilet-7","url":"pract/kolok-01.html#bilet-7","kind":"ticket","label":"Билет 7","title":"Первая аксиома счётности. Предельные точки и сходимость последовательностей","text":"По конспекту: Def. 1, Def. 2, Def. 3, Def. 4, NB 1, Ex. 1, Lm. 1 лекции 2; задачи 2.2.1, 2.2.8, 2.3.4. План ответа на минуту: Def. 1: предельная точка — каждая окрестность содержит точку S, отличную от P; сравнить с точкой прикосновения. Def. 2: сходимость — любая окрестность содержит хвост; в τ_a предел не единстве…","section":"Билет 7. Первая аксиома счётности. Предельные точки и сходимость последовательностей","source":"Коллоквиум, часть 1"},{"id":"bilet-8","url":"pract/kolok-01.html#bilet-8","kind":"ticket","label":"Билет 8","title":"Сепарабельность пространств со второй аксиомой счётности. Контрпример к обратному","text":"По конспекту: Def. 5, Def. 6, Th 2.1, Def. 7, NB 2, Ex. 2 лекции 2; задачи 2.2.4, 2.2.7, 2.2.9. План ответа на минуту: Def. 5: II аксиома — счётная база; пример — рациональные интервалы. Def. 6: всюду плотное — overline S = X ⟺ пересекает каждое непустое открытое; Def. 7: сепарабельность. Th 2.1: по точке из каждого…","section":"Билет 8. Сепарабельность пространств со второй аксиомой счётности. Контрпример к обратному","source":"Коллоквиум, часть 1"},{"id":"bilet-9","url":"pract/kolok-01.html#bilet-9","kind":"ticket","label":"Билет 9","title":"Счётное подпокрытие в пространстве со счётной базой. Компактность","text":"По конспекту: Def. 8, Def. 9, Th 2.2, Def. 10, Ex. 3, Ex. 4 лекции 2; задача 2.2.5. План ответа на минуту: Def. 8–9: покрытие, открытое покрытие, подпокрытие. Th 2.2: при счётной базе из любого открытого покрытия выбирается не более чем счётное подпокрытие. Доказательство: элементы базы, лежащие в элементах покрытия…","section":"Билет 9. Счётное подпокрытие в пространстве со счётной базой. Компактность","source":"Коллоквиум, часть 1"},{"id":"bilet-10","url":"pract/kolok-01.html#bilet-10","kind":"ticket","label":"Билет 10","title":"Локально конечное уточнение покрытия. Паракомпактность и компактность","text":"По конспекту: Def. 11, Def. 12, Ex. 5, Def. 13, NB 3 лекции 2; задача 2.2.6, задача 4.4.3. План ответа на минуту: Def. 11: уточнение — каждый элемент лежит в некотором элементе исходного покрытия; подпокрытие — частный случай. Def. 12: локально конечное — у каждой точки окрестность, задевающая конечное число элемент…","section":"Билет 10. Локально конечное уточнение покрытия. Паракомпактность и компактность","source":"Коллоквиум, часть 1"},{"id":"bilet-11","url":"pract/kolok-01.html#bilet-11","kind":"ticket","label":"Билет 11","title":"Аксиомы отделимости T₁ и T₂. Замкнутость одноточечных множеств. Аксиомы T₃ и T₄","text":"По конспекту: Def. 14, Ex. 6, Lm. 2, Def. 15, Ex. 7, NB 4, NB 5 лекции 2; задачи 2.3.1–2.3.5. План ответа на минуту: Def. 14: T_1 — каждая из двух точек имеет окрестность без другой; не T_1 — связанное двоеточие (Ex. 6). Lm. 2: в T_1 точки замкнуты (и обратно); следствие — конечные множества замкнуты. Def. 15: T_2 —…","section":"Билет 11. Аксиомы отделимости $T_1$ и $T_2$. Замкнутость одноточечных множеств. Аксиомы $T_3$ и $T_4$","source":"Коллоквиум, часть 1"},{"id":"bilet-12","url":"pract/kolok-01.html#bilet-12","kind":"ticket","label":"Билет 12","title":"Прообразы объединения, пересечения и дополнения. Топология прообразов","text":"По конспекту: раздел 3.1, NB 3 лекции 3; топология из блоков лекции 1; задача 3.1.1. План ответа на минуту: Определение f^-1(A) = {x: f(x) ∈ A} — для любого отображения, не обязательно обратимого. Три тождества: прообраз уважает ∪, ∩ и дополнение — доказательство поэлементно, для любых семейств. Образ так не умеет: …","section":"Билет 12. Прообразы объединения, пересечения и дополнения. Топология прообразов","source":"Коллоквиум, часть 1"},{"id":"bilet-13","url":"pract/kolok-01.html#bilet-13","kind":"ticket","label":"Билет 13","title":"Непрерывность в точке. Критерии непрерывности через прообразы и замыкание","text":"По конспекту: Def. 1, NB 1, Th. 3.1, Следствие 1, Lm. 2, NB 2 лекции 3; задачи 3.1.3, 3.1.4. План ответа на минуту: Def. 1: для любой окрестности V ni f(x) есть окрестность U ni x с f(U) ⊆ V — «ε–δ» без чисел; NB 1. Th. 3.1: непрерывно ⟺ прообраз открытого открыт; доказательство в обе стороны. Следствие 1: то же для…","section":"Билет 13. Непрерывность в точке. Критерии непрерывности через прообразы и замыкание","source":"Коллоквиум, часть 1"},{"id":"bilet-14","url":"pract/kolok-01.html#bilet-14","kind":"ticket","label":"Билет 14","title":"Непрерывность композиции, включения подпространства и проекции на сомножитель","text":"По конспекту: Lm. 1, Ex. 1, Th. 3.1 лекции 3; Def. 3, Lm. 2 лекции 1; задачи 3.2.1, 3.2.2, 3.2.5. План ответа на минуту: Lm. 1: (gcirc f)^-1(W) = f^-1(g^-1(W)) и дважды Th. 3.1. Вложение j: A hookrightarrow X: j^-1(V) = A ∩ V — открыто по определению индуцированной топологии. Проекция pr_1: X× Y → X: pr_1^-1(V) = V …","section":"Билет 14. Непрерывность композиции, включения подпространства и проекции на сомножитель","source":"Коллоквиум, часть 1"},{"id":"bilet-15","url":"pract/kolok-01.html#bilet-15","kind":"ticket","label":"Билет 15","title":"Теорема о непрерывном образе компактного множества","text":"По конспекту: Th. 3.2 лекции 3; Def. 10, Ex. 3, Ex. 4 лекции 2; задача 3.3.3, задача 3.5.3. План ответа на минуту: Напомнить Def. 10 (компактность) и что компактность подмножества — в индуцированной топологии. Th. 3.2: f непрерывно, K компактно ⇒ f(K) компактно. Доказательство: покрытие f(K) тянем прообразами на K, …","section":"Билет 15. Теорема о непрерывном образе компактного множества","source":"Коллоквиум, часть 1"},{"id":"bilet-16","url":"pract/kolok-01.html#bilet-16","kind":"ticket","label":"Билет 16","title":"Гомеоморфизм. Критерий гомеоморфизма для непрерывной биекции","text":"По конспекту: Def. 2, Ex. 2, Lm. 3, NB 4, Ex. 3 лекции 3; задачи 3.4.1–3.4.4. План ответа на минуту: Def. 2: биекция, непрерывная вместе с обратной; X simeq Y. Ex. 2: непрерывной биекции мало — id: τ_d → τ_a; ещё [0,2pi) → S^1. Lm. 3: непрерывная биекция — гомеоморфизм ⟺ образы открытых открыты; ключ — (f^-1)^-1(U) …","section":"Билет 16. Гомеоморфизм. Критерий гомеоморфизма для непрерывной биекции","source":"Коллоквиум, часть 1"},{"id":"bilet-17","url":"pract/kolok-01.html#bilet-17","kind":"ticket","label":"Билет 17","title":"Топологические инварианты. Компактность, аксиомы счётности и отделимости","text":"По конспекту: Def. 3, Lm. 4, Ex. 4, Lm. 5 лекции 3; NB 1 лекции 4; задачи 3.5.1–3.5.3. План ответа на минуту: Def. 3: инвариант — свойство, сохраняющееся при гомеоморфизмах. Lm. 4: компактность — через Th. 3.2 в обе стороны. Lm. 5: I, II аксиомы — образ базы есть база; T_1, T_2 — образы разделяющих окрестностей, инъ…","section":"Билет 17. Топологические инварианты. Компактность, аксиомы счётности и отделимости","source":"Коллоквиум, часть 1"},{"id":"bilet-18","url":"pract/kolok-01.html#bilet-18","kind":"ticket","label":"Билет 18","title":"Связность пространства и подмножества. Критерий через открыто-замкнутые множества","text":"По конспекту: Def. 1, Ex. 1, Def. 2, Lm. 1, Ex. 2 лекции 4; задачи 4.1.1–4.1.4, 4.2.3. План ответа на минуту: Def. 1: связно — нельзя разбить на два непустых непересекающихся открытых. Def. 2: подмножество связно, если связно в индуцированной топологии — части разреза открыты в A. Lm. 1: связно ⟺ открыто-замкнуты то…","section":"Билет 18. Связность пространства и подмножества. Критерий через открыто-замкнутые множества","source":"Коллоквиум, часть 1"},{"id":"bilet-19","url":"pract/kolok-01.html#bilet-19","kind":"ticket","label":"Билет 19","title":"Компоненты связности. Объединение связных множеств с общей точкой","text":"По конспекту: Def. 3, Lm. 2, Lm. 3, NB 1 лекции 4; задачи 4.2.1, 4.2.2, 4.4.4. План ответа на минуту: Lm. 2: связное A ⊆ U⊔ V (U,V открыты, не пересекаются) лежит целиком в одном из них. Lm. 3: объединение связных с общей точкой P связно — доказательство через Lm. 2. Def. 3: компонента — максимальное связное подмнож…","section":"Билет 19. Компоненты связности. Объединение связных множеств с общей точкой","source":"Коллоквиум, часть 1"},{"id":"bilet-20","url":"pract/kolok-01.html#bilet-20","kind":"ticket","label":"Билет 20","title":"Связность непрерывного образа. Связность линейно связного пространства","text":"По конспекту: Th. 4.1, NB 1, Def. 4, Def. 5, Lm. 4 лекции 4; задачи 4.2.4, 4.3.2, 4.3.3. План ответа на минуту: Th. 4.1: непрерывный образ связного связен — разрез образа тянем прообразами в разрез X. Следствия: теорема о промежуточном значении; непрерывное в дискретное — константа; NB 1 — связность инвариант. Def. …","section":"Билет 20. Связность непрерывного образа. Связность линейно связного пространства","source":"Коллоквиум, часть 1"},{"id":"bilet-21","url":"pract/kolok-01.html#bilet-21","kind":"ticket","label":"Билет 21","title":"Топологическое многообразие без края. Теорема Брауэра об инвариантности размерности","text":"По конспекту: Def. 6, Th. 4.2, Def. 7, Ex. 3, NB 2 лекции 4; задачи 4.4.1, 4.4.2, 4.4.5. План ответа на минуту: Def. 6: локально евклидово размерности n — у каждой точки открытая окрестность simeq ℝ^n_st. Th. 4.2 (Брауэр, без доказательства): гомеоморфные непустые открытые U ⊆ ℝ^n, V ⊆ ℝ^m ⇒ m = n. Зачем Брауэр: раз…","section":"Билет 21. Топологическое многообразие без края. Теорема Брауэра об инвариантности размерности","source":"Коллоквиум, часть 1"},{"id":"bilet-22","url":"pract/kolok-01.html#bilet-22","kind":"ticket","label":"Билет 22","title":"Примеры к определению многообразия. Окружность, крест и две склеенные прямые","text":"По конспекту: Def. 7, Ex. 3, Ex. 4 лекции 4; Ex. 3, NB 3 лекции 2; задача 4.3.2. План ответа на минуту: Напомнить Def. 7: три условия — паракомпактность, T_2, локальная евклидовость. S^1 — многообразие: T_2 как подпространство ℝ^2, компактна ⇒ паракомпактна, две стереографические карты. Крест xy = 0: локальная евкли…","section":"Билет 22. Примеры к определению многообразия. Окружность, крест и две склеенные прямые","source":"Коллоквиум, часть 1"},{"id":"bilet-23","url":"pract/kolok-01.html#bilet-23","kind":"ticket","label":"Билет 23","title":"Произведение топологических многообразий и его размерность. Тор","text":"По конспекту: Lm. 5, Ex. 5 лекции 4; Lm. 2 лекции 1; Ex. 3 лекции 2; задача 2.3.3, задача 3.2.2. План ответа на минуту: Lm. 5: X^n × Y^m с топологией произведения — многообразие размерности n + m. Локальная евклидовость: U× V simeq A× B ⊆ ℝ^n+m — произведение гомеоморфизмов. Хаусдорфовость произведения; паракомпактн…","section":"Билет 23. Произведение топологических многообразий и его размерность. Тор","source":"Коллоквиум, часть 1"},{"id":"bilet-24","url":"pract/kolok-01.html#bilet-24","kind":"ticket","label":"Билет 24","title":"Топологические подмногообразия. Примеры включений ℝᵐ ⊆ ℝⁿ и Sᵐ ⊆ Sⁿ","text":"По конспекту: Def. 8, Ex. 6, Ex. 5 лекции 4; Def. 3 лекции 1; задача 3.3.2. План ответа на минуту: Def. 8: S ⊆ X^n — подмногообразие размерности m < n, если S с индуцированной топологией — m-многообразие. ℝ^m ⊆ ℝ^n как {(x, 0)}: вложение — гомеоморфизм на образ (обратное — проекция). S^m ⊆ S^n — «экватор»: последние…","section":"Билет 24. Топологические подмногообразия. Примеры включений $\\mathbb{R}^m\\subseteq\\mathbb{R}^n$ и $S^m\\subseteq S^n$","source":"Коллоквиум, часть 1"},{"id":"bilet-1","url":"pract/kolok-02.html#bilet-1","kind":"ticket","label":"Билет 1","title":"Карта, локальные координаты и центрирование карты в точке","text":"По конспекту: Def. 1 лекции 5, NB 1, Def. 2, раздел 5.1. План ответа на минуту: Карта — пара (U, varphi): U ⊆ M, varphi: U → O биекция на открытое O ⊆ ℝ^n. U — носитель, varphi — картирующее отображение, его компоненты x^i: U → ℝ — координатные функции. Локальные координаты точки: varphi(P) = (x^1_P, …, x^n_P), x^i_…","section":"Билет 1. Карта, локальные координаты и центрирование карты в точке","source":"Коллоквиум, часть 2"},{"id":"bilet-2","url":"pract/kolok-02.html#bilet-2","kind":"ticket","label":"Билет 2","title":"C^r-согласованность карт. Замена координат и атлас класса C^r","text":"По конспекту: Def. 3 лекции 5, NB 2, Def. 4, Ex. 1, NB 3. План ответа на минуту: Две карты C^r-согласованы, если носители не пересекаются или на W = U ∩ V образы открыты и psi circ varphi^-1 — C^r-диффеоморфизм. chi = psi circ varphi^-1 — замена координат: y^i = y^i(x^1, …, x^n). Диффеоморфизм: и chi, и chi^-1 класс…","section":"Билет 2. $C^r$-согласованность карт. Замена координат и атлас класса $C^r$","source":"Коллоквиум, часть 2"},{"id":"bilet-3","url":"pract/kolok-02.html#bilet-3","kind":"ticket","label":"Билет 3","title":"Эквивалентность атласов. Максимальный атлас как дифференциальная структура","text":"По конспекту: Def. 5 лекции 5, Lm. 1, Def. 6, Def. 7, Def. 8, раздел 5.2. План ответа на минуту: Карта согласована с атласом, если mathcalA_M ∪ {(U, varphi)} — снова атлас (Def. 5). Lm. 1: все карты, согласованные с mathcalA_M, образуют атлас widetildemathcalA_M — с доказательством через карту U_beta и формулу psici…","section":"Билет 3. Эквивалентность атласов. Максимальный атлас как дифференциальная структура","source":"Коллоквиум, часть 2"},{"id":"bilet-4","url":"pract/kolok-02.html#bilet-4","kind":"ticket","label":"Билет 4","title":"Атласы окружности. Стереографические, угловые и проекционные координаты","text":"По конспекту: Ex. 1 лекции 5, Ex. 3, Ex. 5 лекции 6. План ответа на минуту: Стереографический атлас: проекции из полюсов, α = x/(1-y), beta = x/(1+y), переход beta = 1/α, α ≠ 0. Угловой атлас: углы от Q_0 и от P_0 в (-pi, pi), переход t + pi на (-pi, 0) и t - pi на (0, pi). Проекционный атлас: четыре полуокружности,…","section":"Билет 4. Атласы окружности. Стереографические, угловые и проекционные координаты","source":"Коллоквиум, часть 2"},{"id":"bilet-5","url":"pract/kolok-02.html#bilet-5","kind":"ticket","label":"Билет 5","title":"Различные C^r-структуры на прямой при r ≥ 1. Диффеоморфизм со стандартной прямой","text":"По конспекту: Ex. 2 лекции 5, Def. 7, Def. 1 лекции 7, Def. 3 лекции 7. План ответа на минуту: varphi_α(x) = x при x ⩽ 0, α x при x gt 0; биекция и гомеоморфизм ℝ → ℝ. Переход varphi_α circ varphi_beta^-1: наклоны 1 слева и α/beta справа. При α ≠ beta излом в нуле — переход не дифференцируем, атласы не эквивалентны:…","section":"Билет 5. Различные $C^r$-структуры на прямой при $r \\geqslant 1$. Диффеоморфизм со стандартной прямой","source":"Коллоквиум, часть 2"},{"id":"bilet-6","url":"pract/kolok-02.html#bilet-6","kind":"ticket","label":"Билет 6","title":"Декартово произведение многообразий. Атлас произведения и формула размерности","text":"По конспекту: Def. 9 лекции 5, Lm. 2, Ex. 4, раздел 5.3; топологическая версия — Lm. 5 лекции 4. План ответа на минуту: X = M × N, карты-произведения (U × V, varphi × psi), (varphi × psi)(P, Q) = (varphi(P), psi(Q)). Образ varphi(U) × psi(V) открыт в ℝ^n × ℝ^m = ℝ^n+m. Пересечение произведений — произведение пересеч…","section":"Билет 6. Декартово произведение многообразий. Атлас произведения и формула размерности","source":"Коллоквиум, часть 2"},{"id":"bilet-7","url":"pract/kolok-02.html#bilet-7","kind":"ticket","label":"Билет 7","title":"Топология, индуцированная атласом. Критерий открытости множества в картах","text":"По конспекту: NB 1 лекции 6, Def. 1, NB 2, Lm. 1, NB 3, раздел 6.1. План ответа на минуту: NB 1: так как varphi — биекция, varphi перестановочна с объединениями и пересечениями. Def. 1: O открыто, если varphi(O ∩ U) открыто в ℝ^n для любой карты (U, varphi) ∈ widetildemathcalA_M. Это топология (NB 2): аксиомы провер…","section":"Билет 7. Топология, индуцированная атласом. Критерий открытости множества в картах","source":"Коллоквиум, часть 2"},{"id":"bilet-8","url":"pract/kolok-02.html#bilet-8","kind":"ticket","label":"Билет 8","title":"Открытое подмногообразие. Ограничение карт и размерность","text":"По конспекту: Def. 2 лекции 6, NB 4, NB 3, Def. 1. План ответа на минуту: S ⊂ M открыто; карты ограничиваются: (S ∩ U_α, varphi_α|_S ∩ U_α). Образ varphi_α(S ∩ U_α) открыт — потому что S открыто (Def. 1). Переходы — сужения переходов M на открытые множества: остаются C^r-диффеоморфизмами. Обозначение S ⩽ M, dim S = …","section":"Билет 8. Открытое подмногообразие. Ограничение карт и размерность","source":"Коллоквиум, часть 2"},{"id":"bilet-9","url":"pract/kolok-02.html#bilet-9","kind":"ticket","label":"Билет 9","title":"Первая аксиома счётности на многообразии. Пример многообразия без счётной базы","text":"По конспекту: Lm. 2 лекции 6, Ex. 1, раздел 6.2; аксиомы — Def. 4 и Def. 5 лекции 2. План ответа на минуту: Напомнить первую аксиому: у каждой точки счётная фундаментальная система окрестностей. Lm. 2: τ_M ей удовлетворяет. Окрестности varphi^-1(B(varphi(P), 1/k)). Любая окрестность V ni P содержит координатную V ∩ …","section":"Билет 9. Первая аксиома счётности на многообразии. Пример многообразия без счётной базы","source":"Коллоквиум, часть 2"},{"id":"bilet-10","url":"pract/kolok-02.html#bilet-10","kind":"ticket","label":"Билет 10","title":"Определение дифференцируемого C^r-многообразия. Хаусдорфовость и паракомпактность","text":"По конспекту: Def. 3 лекции 6, Ex. 2, Def. 8 лекции 5, NB 3 лекции 5; топология — Def. 15 (T₂) и Def. 13 лекции 2 (паракомпактность), Def. 7 лекции 4. План ответа на минуту: Множество + максимальный C^r-атлас widetildemathcalA_M → топология τ_M (билет 7). Def. 3: τ_M должна быть хаусдорфовой и паракомпактной; n — ра…","section":"Билет 10. Определение дифференцируемого $C^r$-многообразия. Хаусдорфовость и паракомпактность","source":"Коллоквиум, часть 2"},{"id":"bilet-11","url":"pract/kolok-02.html#bilet-11","kind":"ticket","label":"Билет 11","title":"Критерий совпадения заданной топологии с топологией, индуцированной атласом","text":"По конспекту: Th. 6.1 лекции 6, NB 3; гомеоморфизм — Def. 2 лекции 3. План ответа на минуту: На M две структуры: атлас widetildemathcalA_M (даёт τ_M) и заранее заданная топология τ. Th. 6.1: τ = τ_M ⟺ каждый носитель U открыт в τ и каждая карта — гомеоморфизм U → varphi(U) в τ. Необходимость — NB 3; достаточность — …","section":"Билет 11. Критерий совпадения заданной топологии с топологией, индуцированной атласом","source":"Коллоквиум, часть 2"},{"id":"bilet-12","url":"pract/kolok-02.html#bilet-12","kind":"ticket","label":"Билет 12","title":"Вложенное подмногообразие евклидова пространства. Локальное выпрямление","text":"По конспекту: Def. 4 лекции 6, раздел 6.3; топологическая версия — Def. 8 лекции 4. План ответа на минуту: mathcalE — евклидово, dim mathcalE = d, r ⩾ 1, на подмножествах — топология подпространства. Def. 4: у каждой x ∈ M есть окрестность O_x и C^r-диффеоморфизм varphi_x: O_x → V_x с varphi_x(M ∩ O_x) = V_x ∩ E. E …","section":"Билет 12. Вложенное подмногообразие евклидова пространства. Локальное выпрямление","source":"Коллоквиум, часть 2"},{"id":"bilet-13","url":"pract/kolok-02.html#bilet-13","kind":"ticket","label":"Билет 13","title":"Естественный атлас вложенного подмногообразия и топология подпространства","text":"По конспекту: Lm. 3 лекции 6, Def. 4, Th. 6.1. План ответа на минуту: pi: ℝ^d → ℝ^n — проекция, iota(u) = (u, 0) — вложение; U_x = M ∩ O_x — открытое покрытие M. Карты theta_x = pi circ varphi_x|_U_x, обратные theta_x^-1 = varphi_x^-1 circ iota — гомеоморфизмы на открытые iota^-1(V_x). Переходы theta_y circ theta_x^…","section":"Билет 13. Естественный атлас вложенного подмногообразия и топология подпространства","source":"Коллоквиум, часть 2"},{"id":"bilet-14","url":"pract/kolok-02.html#bilet-14","kind":"ticket","label":"Билет 14","title":"Критерий подмногообразия через ранг локально определяющей функции","text":"По конспекту: Th. 6.2 лекции 6, NB 5, Ex. 5, Def. 4. План ответа на минуту: Th. 6.2: M — вложенное подмногообразие размерности n lt d ⟺ локально M = h^-1(0), h: U_x → ℝ^d-n, rank Dh(x) = d - n. h — локально определяющая функция (NB 5); Dh(x) — матрица (d-n) × d полного ранга, то есть сюръекция. Идея ⇒: h = rho circ …","section":"Билет 14. Критерий подмногообразия через ранг локально определяющей функции","source":"Коллоквиум, часть 2"},{"id":"bilet-15","url":"pract/kolok-02.html#bilet-15","kind":"ticket","label":"Билет 15","title":"Регулярные и особые нулевые уровни. Система Ax = b, окружность и точка возврата","text":"По конспекту: Ex. 3 лекции 6, Ex. 4, Ex. 5, Th. 6.2. План ответа на минуту: Нулевой уровень h^-1(0) регулярен, если в каждой его точке rank Dh = d - n (максимален); иначе есть особые точки. Регулярный уровень — вложенное подмногообразие по Th. 6.2. Ex. 3: Ax = b, rank A = k, b ∈ Im A ⇒ dim = d - k; конкретная матриц…","section":"Билет 15. Регулярные и особые нулевые уровни. Система $Ax = b$, окружность и точка возврата","source":"Коллоквиум, часть 2"},{"id":"bilet-16","url":"pract/kolok-02.html#bilet-16","kind":"ticket","label":"Билет 16","title":"C^r-гладкость отображения в точке и её независимость от выбора карт","text":"По конспекту: Def. 1 лекции 7, NB 1, Lm. 1, раздел 3.1. План ответа на минуту: sigma: M → N C^r в точке P, если найдутся карты U ni P, V с sigma(U) ⊂ V и widehatsigma = psi circ sigma circ varphi^-1 класса C^r. widehatsigma — координатный представитель; C^r во всех точках — C^r на M (NB 1). Lm. 1: свойство не зависи…","section":"Билет 16. $C^r$-гладкость отображения в точке и её независимость от выбора карт","source":"Коллоквиум, часть 2"},{"id":"bilet-17","url":"pract/kolok-02.html#bilet-17","kind":"ticket","label":"Билет 17","title":"C^r-отображение на произвольном подмножестве. Локальное продолжение","text":"По конспекту: Def. 2 лекции 7, Def. 1, Def. 4 (кривые используют Def. 2). План ответа на минуту: Def. 1 работает в открытых окрестностях; для S ⊂ M произвольного (отрезок, замкнутое множество) нужен Def. 2. Def. 2: у каждой P ∈ S есть открытая O_P ⊂ M и C^r-отображение widetildesigma: O_P → N, совпадающее с sigma на…","section":"Билет 17. $C^r$-отображение на произвольном подмножестве. Локальное продолжение","source":"Коллоквиум, часть 2"},{"id":"bilet-18","url":"pract/kolok-02.html#bilet-18","kind":"ticket","label":"Билет 18","title":"C^r-диффеоморфизм. Открытый диск и плоскость. Гомеоморфизм x ↦ x³","text":"По конспекту: Def. 3 лекции 7, Ex. 1, Ex. 2, Def. 1. План ответа на минуту: Диффеоморфизм — гомеоморфизм, у которого sigma и sigma^-1 класса C^r; многообразия диффеоморфны. Ex. 1: D^2 → ℝ^2, (x, y) mapsto (x/z, y/z), z = √(1 - x^2 - y^2); обратное (u, v) mapsto (u, v)/√(1 + u^2 + v^2). Геометрия: подъём на полусферу…","section":"Билет 18. $C^r$-диффеоморфизм. Открытый диск и плоскость. Гомеоморфизм $x \\mapsto x^3$","source":"Коллоквиум, часть 2"},{"id":"bilet-19","url":"pract/kolok-02.html#bilet-19","kind":"ticket","label":"Билет 19","title":"Гладкие кривые и вещественные функции на многообразии. Координатные представители","text":"По конспекту: Def. 4 лекции 7, NB 2, Ex. 3, Def. 5, NB 3, раздел 3.2. План ответа на минуту: Кривая — непрерывное gamma: I → M; C^r — в смысле Def. 2 (на подмножестве), гладкая при r = ∞. Представитель кривой widehatgamma = varphi circ gamma: gamma^-1(U) → varphi(U), widehatgamma(t) = (x^1(t), …, x^n(t)). Функция — …","section":"Билет 19. Гладкие кривые и вещественные функции на многообразии. Координатные представители","source":"Коллоквиум, часть 2"},{"id":"bilet-20","url":"pract/kolok-02.html#bilet-20","kind":"ticket","label":"Билет 20","title":"Носитель функции. Лемма о срезающей функции и гладкое продолжение нулём","text":"По конспекту: NB 4 лекции 7, Lm. 2, Def. 6, NB 5, раздел 3.3. План ответа на минуту: supp f — замыкание множества {f ≠ 0} (NB 4). Lm. 2: для компакта K ⊂ O есть гладкая beta: M → [0, 1], beta|_K = 1, suppbeta компактен и лежит в O — срезающая функция (Def. 6). Идея: ядро g = e^-(t-r)^-1e^(t-s)^-1 на (r, s), интеграл…","section":"Билет 20. Носитель функции. Лемма о срезающей функции и гладкое продолжение нулём","source":"Коллоквиум, часть 2"},{"id":"bilet-21","url":"pract/kolok-02.html#bilet-21","kind":"ticket","label":"Билет 21","title":"Разбиение единицы, подчинённое открытому покрытию. Теорема существования","text":"По конспекту: Def. 7 лекции 7, Def. 8, Th. 3.1, Lm. 2; паракомпактность — Def. 13 лекции 2, локальная конечность — Def. 12. План ответа на минуту: Def. 7: гладкие varphi_α ∈ [0, 1], носители локально конечны, Σ_α varphi_α = 1 (в каждой точке сумма конечна). Def. 8: подчинено покрытию {O_α}, если suppvarphi_α ⊂ O_α —…","section":"Билет 21. Разбиение единицы, подчинённое открытому покрытию. Теорема существования","source":"Коллоквиум, часть 2"},{"id":"v1-1","url":"pract/kr-01.html#v1-1","kind":"task","label":"В1 · 1","title":"Int, Cl и ∂ в двух топологиях","text":"На X = [0, +∞) рассмотрим A = {2} ∪ (3, 4). Найдите Int_X A, Cl_X A, ∂_X A (a) в топологии стрелки τ_→; (b) в стандартной топологии.","section":"Вариант 1","source":"Пробная КР 1"},{"id":"v1-2","url":"pract/kr-01.html#v1-2","kind":"task","label":"В1 · 2","title":"Граница объединения","text":"(a) Докажите, что в любом топологическом пространстве ∂(A ∪ B) ⊆ ∂ A ∪ ∂ B. (b) Верно ли Int(Cl A) = Cl(Int A)? Докажите или приведите контрпример.","section":"Вариант 1","source":"Пробная КР 1"},{"id":"v1-3","url":"pract/kr-01.html#v1-3","kind":"task","label":"В1 · 3","title":"Лучи: база или предбаза","text":"Является ли семейство sigma = {(a, +∞): a ∈ ℝ} ∪ {(-∞, b): b ∈ ℝ} базой какой-нибудь топологии на ℝ? Является ли оно предбазой стандартной топологии?","section":"Вариант 1","source":"Пробная КР 1"},{"id":"v1-4","url":"pract/kr-01.html#v1-4","kind":"task","label":"В1 · 4","title":"Топология выделенной точки","text":"На ℝ рассмотрим τ = {∅} ∪ {U ⊆ ℝ: 0 ∈ U}. (a) Докажите, что это топология. (b) Проверьте T_1 и T_2. (c) Сепарабельно ли пространство? (d) Проверьте первую и вторую аксиомы счётности.","section":"Вариант 1","source":"Пробная КР 1"},{"id":"v1-5","url":"pract/kr-01.html#v1-5","kind":"task","label":"В1 · 5","title":"Разрыв и стрелка","text":"f: ℝ → [0, +∞), f(x) = x^2 при x < 1 и f(x) = 2x при x ⩾ 1. (a) Найдите точки разрыва при стандартной топологии на [0,+∞) и предъявите свидетеля разрыва. (b) Непрерывно ли f как отображение в стрелку X_→? (c) Что изменится, если положить f(1) = 1?","section":"Вариант 1","source":"Пробная КР 1"},{"id":"v1-6","url":"pract/kr-01.html#v1-6","kind":"task","label":"В1 · 6","title":"Полоса и квадрат; цилиндры","text":"(a) Постройте гомеоморфизм полосы ℝ × (-1, 1) на открытый квадрат (0,1)^2. (b) Докажите, что S^1 × [0,1] и S^1 × ℝ не гомеоморфны.","section":"Вариант 1","source":"Пробная КР 1"},{"id":"v1-7","url":"pract/kr-01.html#v1-7","kind":"task","label":"В1 · 7","title":"Прямая и плоскость","text":"(a) Докажите, что ℝ и ℝ^2 не гомеоморфны. (b) Пусть f: ℝ → ℝ непрерывна и f(x)^2 = 1 для всех x. Докажите, что f постоянна.","section":"Вариант 1","source":"Пробная КР 1"},{"id":"v2-1","url":"pract/kr-01.html#v2-1","kind":"task","label":"В2 · 1","title":"Int, Cl и ∂ в τ_CF и τ_st","text":"На ℝ найдите Int, Cl, ∂ множеств B = ℝ\\{0,1}, C = [0,1] ∪ {5} и D = {1,2,3} в топологии конечных дополнений. Совпадают ли ответы для B со стандартной топологией?","section":"Вариант 2","source":"Пробная КР 1"},{"id":"v2-2","url":"pract/kr-01.html#v2-2","kind":"task","label":"В2 · 2","title":"Замыкание разности","text":"Докажите, что ClA \\ ClB ⊆ Cl(A \\ B). Верно ли обратное включение?","section":"Вариант 2","source":"Пробная КР 1"},{"id":"v2-3","url":"pract/kr-01.html#v2-3","kind":"task","label":"В2 · 3","title":"Семейство на трёх точках","text":"X = {a, b, c}, beta = {{a}, {a,b}, {b,c}}. Является ли beta базой какой-нибудь топологии? Если нет, добавьте одно множество так, чтобы стало базой, и выпишите порождённую топологию.","section":"Вариант 2","source":"Пробная КР 1"},{"id":"v2-4","url":"pract/kr-01.html#v2-4","kind":"task","label":"В2 · 4","title":"Пределы одной последовательности в трёх топологиях","text":"Найдите все пределы последовательности x_n = tfrac1n (a) в ℝ_st; (b) в ℝ_CF; (c) в стрелке X_→. Для каждого пространства скажите, выполнена ли T_2, и согласуйте это с ответом.","section":"Вариант 2","source":"Пробная КР 1"},{"id":"v2-5","url":"pract/kr-01.html#v2-5","kind":"task","label":"В2 · 5","title":"Многочлены в топологию конечных дополнений","text":"(a) Докажите, что любой многочлен p: ℝ_st → ℝ_CF непрерывен. (b) Непрерывно ли тождественное ℝ_CF → ℝ_st?","section":"Вариант 2","source":"Пробная КР 1"},{"id":"v2-6","url":"pract/kr-01.html#v2-6","kind":"task","label":"В2 · 6","title":"Полуплоскость и инварианты","text":"(a) Постройте гомеоморфизм открытой полуплоскости {y > 0} на ℝ^2. (b) Докажите, что ℝ_st, ℝ_CF и [0,1]_st попарно негомеоморфны.","section":"Вариант 2","source":"Пробная КР 1"},{"id":"v2-7","url":"pract/kr-01.html#v2-7","kind":"task","label":"В2 · 7","title":"Полуинтервал и интервал; крест","text":"(a) Докажите, что [0,1) и (0,1) не гомеоморфны. (b) Докажите, что крест C = {(x,y) ∈ ℝ^2: xy = 0} связен.","section":"Вариант 2","source":"Пробная КР 1"},{"id":"task-1","url":"pract/pract-01.html#task-1","kind":"task","label":"Задача 1","title":"Все топологии на двух точках","text":"Найдите все топологии на множестве X = {a, b}. перебор сложность 1/5","section":"Основные задачи","source":"Листок 1"},{"id":"task-2","url":"pract/pract-01.html#task-2","kind":"task","label":"Задача 2","title":"Связанное двоеточие: Cl и Int точки","text":"X = {0, 1}, τ = {∅, {0}, {0,1}}. (a) Замкнуто ли {1}? (b) Найдите Cl({1}). (c) Найдите Int({1}). Int / Cl по определению сложность 1/5","section":"Основные задачи","source":"Листок 1"},{"id":"task-3","url":"pract/pract-01.html#task-3","kind":"task","label":"Задача 3","title":"Int и Cl на прямой","text":"В ⟨ℝ, τ_st⟩ найдите Intbig((0,1] ∪ {2}big) и Clbig({1/n: n ∈ ℕ}big). Int / Cl на прямой сложность 1/5","section":"Основные задачи","source":"Листок 1"},{"id":"task-4","url":"pract/pract-01.html#task-4","kind":"task","label":"Задача 4","title":"Тождества для Int и Cl","text":"Верно ли: (a) A ⊆ B ⇒ IntA ⊆ IntB; (b) Int(IntA) = IntA; (c) Int(A∩ B) = IntA ∩ IntB; (d) Int(A∪ B) = IntA ∪ IntB; (e) Cl(A∪ B) = ClA ∪ ClB; (f) Cl(A∩ B) = ClA ∩ ClB? Для неверных — контрпример и включение, верное всегда. доказательство / контрпример сложность 2/5 частый тип на КР","section":"Основные задачи","source":"Листок 1"},{"id":"task-5","url":"pract/pract-01.html#task-5","kind":"task","label":"Задача 5","title":"Int, Cl, граница относительно разных пространств","text":"X = [0,1) × [0,1) ⊆ ℝ^2, S = {(x^1, x^2): 0 ⩽ x^1 ⩽ tfrac12,\\ tfrac12 < x^2 < 1}. Найдите внутренность, замыкание и границу S относительно ℝ^2, X и самого S. индуцированная топология сложность 3/5 частый тип на КР","section":"Основные задачи","source":"Листок 1"},{"id":"task-6","url":"pract/pract-01.html#task-6","kind":"task","label":"Задача 6","title":"Конечная выборка дискретна","text":"D = {x_1, …, x_m} ⊆ ℝ^n, точки различны. (a) Докажите, что топология на D дискретна. (b) Найдите Int_D A, Cl_D A, ∂_D A и сравните с теми же в ℝ^n. (c) Что изменится при движении точек? индуцированная топология сложность 2/5","section":"Основные задачи","source":"Листок 1"},{"id":"task-7","url":"pract/pract-01.html#task-7","kind":"task","label":"Задача 7","title":"Локальная устойчивость классификатора","text":"Классификатор относит A к классу 1, X \\ A — к классу 0. Решение локально устойчиво в x, если есть открытая U ni x одного класса с x. (a) Докажите, что множество точек устойчивости равно Int_X A ∪ Int_X(X\\ A), а остальные точки — ∂_X A. (b) X = ℝ^2, A = {x_1 ⩾ 0}. определения Int и ∂ сложность 2/5","section":"Основные задачи","source":"Листок 1"},{"id":"task-8","url":"pract/pract-01.html#task-8","kind":"task","label":"Задача 8","title":"Шары B₂ и B∞ задают одну топологию","text":"(a) Докажите B_2(x,r) ⊆ B_∞(x,r) ⊆ B_2(x, sqrt n r). (b) Докажите, что оба семейства — базы стандартной топологии ℝ^n. (c) Равносильны ли при n ⩾ 2 условия B_2(x,r) ⊆ A и B_∞(x,r) ⊆ A? базы сложность 2/5","section":"Основные задачи","source":"Листок 1"},{"id":"task-9","url":"pract/pract-01.html#task-9","kind":"task","label":"Задача 9","title":"τ_CF и стрелка","text":"(a) В τ_CF на ℝ найдите Cl{1,2,3}, Cl ℕ, Int(0,1), ∂[0,1]. (b) В стрелке на [0,+∞) найдите Cl{1}, Int[0,1]. Открыто ли [0,5)? нестандартные топологии сложность 2/5 частый тип на КР","section":"Основные задачи","source":"Листок 1"},{"id":"task-10","url":"pract/pract-01.html#task-10","kind":"task","label":"Задача 10","title":"Граница рациональных из (0,1)","text":"S = ℚ ∩ (0,1). Найдите ∂ S, Int(∂ S), ∂(∂ S). плотность ℚ сложность 2/5","section":"Основные задачи","source":"Листок 1"},{"id":"task-11","url":"pract/pract-01.html#task-11","kind":"task","label":"Задача 11","title":"Вероятностный симплекс","text":"Δ = {p ∈ ℝ^3: p_i ⩾ 0, Σ p_i = 1}, H = {Σ p_i = 1}. (a) Внутренность и граница Δ в ℝ^3 и в H. (b) Открыто ли U = {p ∈ Δ: p_1 > tfrac12} в Δ? Найдите ∂_Δ U. индуцированная топология сложность 2/5","section":"Дополнительные задачи","source":"Листок 1"},{"id":"task-12","url":"pract/pract-01.html#task-12","kind":"task","label":"Задача 12","title":"Топология из блоков","text":"X разбито на блоки C_1, …, C_k, τ — все объединения блоков. (a) τ — топология. (b) Выразите IntA, ClA через блоки. (c) Посчитайте для A = {a,b,c}, C_1 = {a,b}, C_2 = {c,d}, C_3 = {e,f}. (d) C_2 разбился на {c}, {d} — что стало с топологией и с IntA, ClA? конечные топологии сложность 2/5","section":"Дополнительные задачи","source":"Листок 1"},{"id":"task-13","url":"pract/pract-01.html#task-13","kind":"task","label":"Задача 13","title":"Полупространства — предбаза ℝⁿ","text":"Докажите, что {x_j < a}, {x_j > a}, a ∈ ℚ, j = 1,…,n, — предбаза стандартной топологии. Как получить прямоугольник с рациональными концами? предбаза сложность 2/5","section":"Дополнительные задачи","source":"Листок 1"},{"id":"task-14","url":"pract/pract-01.html#task-14","kind":"task","label":"Задача 14","title":"Точка 0 открыта и замкнута","text":"τ ⊇ τ_st, и лучи (-∞,0], [0,+∞) открыты. Докажите, что {0} открыто и замкнуто. Замкнуты ли лучи? аксиомы сложность 2/5","section":"Дополнительные задачи","source":"Листок 1"},{"id":"task-15","url":"pract/pract-01.html#task-15","kind":"task","label":"Задача 15","title":"Добавить точку ко всем открытым","text":"y ∉ X, Y = X ∪ {y}. Является ли {{y} ∪ T: T ∈ τ_X} ∪ {∅} топологией на Y? аксиомы сложность 1/5","section":"Дополнительные задачи","source":"Листок 1"},{"id":"task-16","url":"pract/pract-01.html#task-16","kind":"task","label":"Задача 16","title":"Три открытых множества с общей границей","text":"Постройте три попарно различных открытых подмножества ℝ с одной и той же границей. граница сложность 1/5","section":"Дополнительные задачи","source":"Листок 1"},{"id":"task-2-1-1","url":"pract/pract-02.html#task-2-1-1","kind":"task","label":"Задача 2.1.1","title":"Одна база — одна топология","text":"Могут ли различные топологии иметь одну и ту же базу? Приведите две разные базы одной топологии. базы сложность 1/5","section":"2.1 Базы и предбазы","source":"Листок 2"},{"id":"task-2-1-2","url":"pract/pract-02.html#task-2-1-2","kind":"task","label":"Задача 2.1.2","title":"Базы дискретной и антидискретной","text":"Найдите базы τ_d и τ_a. Какие множества входят в любую базу τ_d? базы сложность 1/5","section":"2.1 Базы и предбазы","source":"Листок 2"},{"id":"task-2-1-3","url":"pract/pract-02.html#task-2-1-3","kind":"task","label":"Задача 2.1.3","title":"Какие семейства интервалов — базы","text":"Базы ли τ_st: (a) {(a,b): a,b ∈ ℚ}; (b) {(x - tfrac1n, x + tfrac1n)}; (c) {(x-1, x+1): x ∈ ℝ}? базы сложность 2/5","section":"2.1 Базы и предбазы","source":"Листок 2"},{"id":"task-2-1-4","url":"pract/pract-02.html#task-2-1-4","kind":"task","label":"Задача 2.1.4","title":"След базы — база подпространства","text":"beta — база топологии на X, A ⊆ X. Докажите: {A ∩ B: B ∈ beta} — база индуцированной топологии на A. база + подпространство сложность 2/5","section":"2.1 Базы и предбазы","source":"Листок 2"},{"id":"task-2-1-5","url":"pract/pract-02.html#task-2-1-5","kind":"task","label":"Задача 2.1.5","title":"База произведения","text":"beta_X, beta_Y — базы. Докажите, что {B × C} — база топологии произведения. Опишите базу на матрицах p × q. база + произведение сложность 2/5","section":"2.1 Базы и предбазы","source":"Листок 2"},{"id":"task-2-1-6","url":"pract/pract-02.html#task-2-1-6","kind":"task","label":"Задача 2.1.6","title":"Конечный набор порогов","text":"Пороги a_1 < … < a_m, предбаза sigma = {ℝ} ∪ {(-∞, a_i), (a_i, +∞)}. Минимальная окрестность x ∈ (a_i, a_i+1)? Почему топология строго слабее стандартной? Что будет со всеми рациональными порогами? предбаза сложность 2/5","section":"2.1 Базы и предбазы","source":"Листок 2"},{"id":"task-2-1-7","url":"pract/pract-02.html#task-2-1-7","kind":"task","label":"Задача 2.1.7","title":"Прямая Зоргенфрея","text":"Докажите, что {[a,b): a < b} — база некоторой топологии. Сравните со стандартной. Th. 1.1 сложность 2/5 частый тип на КР","section":"2.1 Базы и предбазы","source":"Листок 2"},{"id":"task-2-2-1","url":"pract/pract-02.html#task-2-2-1","kind":"task","label":"Задача 2.2.1","title":"Сходимость в τ_d и τ_a","text":"Опишите все сходящиеся последовательности и их пределы в дискретной и антидискретной топологиях. сходимость сложность 1/5","section":"2.2 Счётность и покрытия","source":"Листок 2"},{"id":"task-2-2-2","url":"pract/pract-02.html#task-2-2-2","kind":"task","label":"Задача 2.2.2","title":"Аксиомы счётности для τ_d, τ_a и стрелки","text":"Исследуйте I и II аксиомы счётности для τ_d, τ_a и стрелки на [0, +∞). счётность сложность 2/5 частый тип на КР","section":"2.2 Счётность и покрытия","source":"Листок 2"},{"id":"task-2-2-3","url":"pract/pract-02.html#task-2-2-3","kind":"task","label":"Задача 2.2.3","title":"II ⇒ I и наследование подпространствами","text":"Докажите, что II влечёт I. Наследуются ли аксиомы подпространствами? счётность сложность 2/5","section":"2.2 Счётность и покрытия","source":"Листок 2"},{"id":"task-2-2-4","url":"pract/pract-02.html#task-2-2-4","kind":"task","label":"Задача 2.2.4","title":"Счётное плотное в ℝⁿ","text":"Предъявите счётное всюду плотное подмножество ℝ^n. Может ли конечная выборка быть всюду плотной? плотность сложность 1/5","section":"2.2 Счётность и покрытия","source":"Листок 2"},{"id":"task-2-2-5","url":"pract/pract-02.html#task-2-2-5","kind":"task","label":"Задача 2.2.5","title":"ε-сеть на компакте","text":"K ⊆ ℝ^n — непустой компакт, ε > 0. Докажите, что есть конечное D_ε ⊆ K, такое что каждая точка K ближе ε к какой-то точке D_ε. Может ли одно конечное D подойти для всех ε при бесконечном K? компактность сложность 2/5","section":"2.2 Счётность и покрытия","source":"Листок 2"},{"id":"task-2-2-6","url":"pract/pract-02.html#task-2-2-6","kind":"task","label":"Задача 2.2.6","title":"Два покрытия прямой","text":"mathcalU = {(-n,n)}, mathcalV = {(k-1, k+1): k ∈ ℤ}. Локальная конечность? Конечные подпокрытия? Уточнения друг друга? покрытия сложность 2/5 частый тип на КР","section":"2.2 Счётность и покрытия","source":"Листок 2"},{"id":"task-2-2-7","url":"pract/pract-02.html#task-2-2-7","kind":"task","label":"Задача 2.2.7","title":"Плотные множества в τ_CF и τ_CC","text":"Какие подмножества ℝ всюду плотны в топологиях конечных и счётных дополнений? Сепарабельность? Аксиомы счётности? плотность, счётность сложность 3/5","section":"2.2 Счётность и покрытия","source":"Листок 2"},{"id":"task-2-2-8","url":"pract/pract-02.html#task-2-2-8","kind":"task","label":"Задача 2.2.8","title":"Замыкание через последовательности","text":"X удовлетворяет I. Докажите: x ∈ overlineA ⟺ есть последовательность из A, сходящаяся к x. Выведите критерий замкнутости. I аксиома сложность 3/5 частый тип на КР","section":"2.2 Счётность и покрытия","source":"Листок 2"},{"id":"task-2-2-9","url":"pract/pract-02.html#task-2-2-9","kind":"task","label":"Задача 2.2.9","title":"Дизъюнктные открытые в сепарабельном","text":"Докажите: в сепарабельном пространстве семейство попарно непересекающихся непустых открытых множеств не более чем счётно. плотность сложность 2/5","section":"2.2 Счётность и покрытия","source":"Листок 2"},{"id":"task-2-3-1","url":"pract/pract-02.html#task-2-3-1","kind":"task","label":"Задача 2.3.1","title":"T₁ и T₂ для стандартных примеров","text":"Проверьте T_1, T_2 для τ_d, τ_a (не менее двух точек), связанного двоеточия и стрелки. отделимость сложность 1/5 частый тип на КР","section":"2.3 Аксиомы отделимости","source":"Листок 2"},{"id":"task-2-3-2","url":"pract/pract-02.html#task-2-3-2","kind":"task","label":"Задача 2.3.2","title":"T₁ ⟺ точки замкнуты","text":"Докажите: X — T_1 ⟺ одноточечные множества замкнуты. Если в T_1 у каждой точки есть конечная открытая окрестность, то пространство дискретно. отделимость сложность 2/5","section":"2.3 Аксиомы отделимости","source":"Листок 2"},{"id":"task-2-3-3","url":"pract/pract-02.html#task-2-3-3","kind":"task","label":"Задача 2.3.3","title":"Хаусдорфовость наследуется","text":"Подпространство и произведение хаусдорфовых пространств хаусдорфовы. отделимость сложность 2/5","section":"2.3 Аксиомы отделимости","source":"Листок 2"},{"id":"task-2-3-4","url":"pract/pract-02.html#task-2-3-4","kind":"task","label":"Задача 2.3.4","title":"Единственность предела","text":"Докажите единственность предела в хаусдорфовом пространстве. К чему сходится последовательность различных чисел в τ_CF? Хватает ли T_1? отделимость, сходимость сложность 2/5 частый тип на КР","section":"2.3 Аксиомы отделимости","source":"Листок 2"},{"id":"task-2-3-5","url":"pract/pract-02.html#task-2-3-5","kind":"task","label":"Задача 2.3.5","title":"τ_CC: предел единственен без T₂","text":"Проверьте T_1, T_2 для τ_CC на ℝ. Докажите единственность предела. Почему это не противоречит предыдущей задаче? отделимость сложность 3/5","section":"2.3 Аксиомы отделимости","source":"Листок 2"},{"id":"task-2-3-6","url":"pract/pract-02.html#task-2-3-6","kind":"task","label":"Задача 2.3.6","title":"Видны только первые k признаков","text":"U(a,r) = {x ∈ ℝ^n: Σ_j=1^k (x_j - a_j)^2 < r^2}, k < n. База ли это? Какие точки неразличимы? T_1, T_2? Что при k = n? база, отделимость сложность 3/5","section":"2.3 Аксиомы отделимости","source":"Листок 2"},{"id":"task-3-1-1","url":"pract/pract-03.html#task-3-1-1","kind":"task","label":"Задача 3.1.1","title":"Инъективность и сюръективность композиции","text":"Докажите: g circ f инъективно ⇒ f инъективно; g circ f сюръективно ⇒ g сюръективно. Верны ли обратные утверждения? отображения множеств сложность 1/5","section":"3.1 Непрерывность и выбор топологии","source":"Листок 3"},{"id":"task-3-1-2","url":"pract/pract-03.html#task-3-1-2","kind":"task","label":"Задача 3.1.2","title":"Непрерывные отображения между ℝ_d, ℝ_a, ℝ_st","text":"Примеры непрерывных ℝ_d → ℝ_st, ℝ_a → ℝ_st, ℝ_st → ℝ_d, ℝ_st → ℝ_a. Когда непрерывно тождественное? непрерывность сложность 1/5 частый тип на КР","section":"3.1 Непрерывность и выбор топологии","source":"Листок 3"},{"id":"task-3-1-3","url":"pract/pract-03.html#task-3-1-3","kind":"task","label":"Задача 3.1.3","title":"Найти точки разрыва","text":"f: [0,2] → [0,2], f(x) = x при 0 ⩽ x < 1, f(x) = 3 - x при 1 ⩽ x ⩽ 2. Найдите точки разрыва и для каждой предъявите открытую окрестность f(x_0), прообраз которой не содержит окрестности x_0. разрыв по Th. 3.1 сложность 2/5 частый тип на КР","section":"3.1 Непрерывность и выбор топологии","source":"Листок 3"},{"id":"task-3-1-4","url":"pract/pract-03.html#task-3-1-4","kind":"task","label":"Задача 3.1.4","title":"Скачок вверх в стрелку","text":"f: [0,2] → X_→, f(x) = x при x ⩽ 1, f(x) = x + 1 при x > 1. Непрерывно ли? А если на [0,+∞) стандартная топология? непрерывность сложность 2/5 частый тип на КР","section":"3.1 Непрерывность и выбор топологии","source":"Листок 3"},{"id":"task-3-2-1","url":"pract/pract-03.html#task-3-2-1","kind":"task","label":"Задача 3.2.1","title":"Проекция квадрата на сторону","text":"Докажите непрерывность p: [0,1]^2 → [0,1]×{0}, p(x,y) = (x, 0). непрерывность сложность 1/5","section":"3.2 Координаты, матрицы и преобразования признаков","source":"Листок 3"},{"id":"task-3-2-2","url":"pract/pract-03.html#task-3-2-2","kind":"task","label":"Задача 3.2.2","title":"Непрерывность по координатам","text":"f = (f^1, …, f^n): X → ℝ^n непрерывно ⟺ непрерывны все f^j. база произведения сложность 2/5 частый тип на КР","section":"3.2 Координаты, матрицы и преобразования признаков","source":"Листок 3"},{"id":"task-3-2-3","url":"pract/pract-03.html#task-3-2-3","kind":"task","label":"Задача 3.2.3","title":"Произведение матриц непрерывно","text":"f: X → Mat(p,q), g: X → Mat(q,r) непрерывны. Докажите непрерывность x mapsto f(x)g(x). непрерывность сложность 2/5","section":"3.2 Координаты, матрицы и преобразования признаков","source":"Листок 3"},{"id":"task-3-2-4","url":"pract/pract-03.html#task-3-2-4","kind":"task","label":"Задача 3.2.4","title":"Множество решений замкнуто","text":"f^1, …, f^n: X → ℝ непрерывны. Докажите, что {f^1 = … = f^n = 0} замкнуто. А {f^j ⩽ 0\\ ∀ j}? Следствие 1 сложность 1/5","section":"3.2 Координаты, матрицы и преобразования признаков","source":"Листок 3"},{"id":"task-3-2-5","url":"pract/pract-03.html#task-3-2-5","kind":"task","label":"Задача 3.2.5","title":"Непрерывность нейросети","text":"h_0 = x, h_j = rho(W_j h_j-1 + b_j), rho = ReLU. Докажите непрерывность h_L по x, а также совместную по x и всем W_j, b_j. композиция сложность 2/5","section":"3.2 Координаты, матрицы и преобразования признаков","source":"Листок 3"},{"id":"task-3-2-6","url":"pract/pract-03.html#task-3-2-6","kind":"task","label":"Задача 3.2.6","title":"Нормировка вектора","text":"N(x) = x/\\|x\\|, ℝ^n\\{0} → S^n-1. Непрерывность, сюръективность, N^-1({u}), можно ли доопределить в нуле? непрерывность сложность 2/5","section":"3.2 Координаты, матрицы и преобразования признаков","source":"Листок 3"},{"id":"task-3-3-1","url":"pract/pract-03.html#task-3-3-1","kind":"task","label":"Задача 3.3.1","title":"Гомеоморфизм сохраняет Cl, Int, ∂","text":"f — гомеоморфизм. Докажите f(ClA) = Clf(A), f(IntA) = Intf(A), f(∂ A) = ∂ f(A). гомеоморфизм сложность 2/5 частый тип на КР","section":"3.3 Гомеоморфизмы, графики и компактность","source":"Листок 3"},{"id":"task-3-3-2","url":"pract/pract-03.html#task-3-3-2","kind":"task","label":"Задача 3.3.2","title":"График непрерывной функции","text":"f: X → Y непрерывно, Gamma_f = {(x, f(x))} ⊆ X × Y. (a) Gamma_f simeq X. (b) При хаусдорфовом Y график замкнут. гомеоморфизм, T₂ сложность 3/5","section":"3.3 Гомеоморфизмы, графики и компактность","source":"Листок 3"},{"id":"task-3-3-3","url":"pract/pract-03.html#task-3-3-3","kind":"task","label":"Задача 3.3.3","title":"Минимум лосса на компакте","text":"Theta ⊆ ℝ^d — непустой компакт, f_j непрерывны, L(theta) = Σ_j (f_j(theta) - y_j)^2. Докажите, что минимум достигается, а множество минимизаторов непусто и компактно. Пример без минимума при некомпактном Theta. Th. 3.2 сложность 2/5 частый тип на КР","section":"3.3 Гомеоморфизмы, графики и компактность","source":"Листок 3"},{"id":"task-3-4-1","url":"pract/pract-03.html#task-3-4-1","kind":"task","label":"Задача 3.4.1","title":"Шесть областей, гомеоморфных плоскости","text":"Постройте гомеоморфизм с ℝ^2: (a) (0,1)^2; (b) (0,+∞)×(0,1); (c) {x^2+y^2 < 1}; (d) {x > y > 0}; (e) {x^2+y^2<1, x>y>0}; (f) {x^2+y^2<1, y>0}. построение гомеоморфизма сложность 3/5 частый тип на КР","section":"3.4 Построение гомеоморфизмов","source":"Листок 3"},{"id":"task-3-4-2","url":"pract/pract-03.html#task-3-4-2","kind":"task","label":"Задача 3.4.2","title":"Круг в квадрат","text":"Постройте гомеоморфизм D^2 → Q = [-1,1]^2, переводящий S^1 в ∂ Q. Проверьте непрерывность в нуле. построение гомеоморфизма сложность 3/5","section":"3.4 Построение гомеоморфизмов","source":"Листок 3"},{"id":"task-3-4-3","url":"pract/pract-03.html#task-3-4-3","kind":"task","label":"Задача 3.4.3","title":"Цилиндры и кольца","text":"Постройте S^1×ℝ → {1 < \\|x\\| < 2} и S^1×[0,1] → {1 ⩽ \\|x\\| ⩽ 2}. Чем различаются построения? построение гомеоморфизма сложность 2/5","section":"3.4 Построение гомеоморфизмов","source":"Листок 3"},{"id":"task-3-4-4","url":"pract/pract-03.html#task-3-4-4","kind":"task","label":"Задача 3.4.4","title":"Проколотая плоскость, проколотый круг, внешность круга","text":"Докажите, что ℝ^2\\{0}, {0 < x^2+y^2 < 1}, {x^2+y^2>1} гомеоморфны. Укажите замену радиуса. построение гомеоморфизма сложность 2/5","section":"3.4 Построение гомеоморфизмов","source":"Листок 3"},{"id":"task-3-5-1","url":"pract/pract-03.html#task-3-5-1","kind":"task","label":"Задача 3.5.1","title":"Окружность и прямая","text":"Докажите, что S^1 notsimeq ℝ_st. А в дискретных топологиях? инварианты сложность 1/5 частый тип на КР","section":"3.5 Инварианты и негомеоморфность","source":"Листок 3"},{"id":"task-3-5-2","url":"pract/pract-03.html#task-3-5-2","kind":"task","label":"Задача 3.5.2","title":"Пять попарно негомеоморфных пространств","text":"Покажите, что ℤ_st, ℚ_st, ℝ_st, ℝ_CF, X_→ попарно негомеоморфны. инварианты сложность 2/5 частый тип на КР","section":"3.5 Инварианты и негомеоморфность","source":"Листок 3"},{"id":"task-3-5-3","url":"pract/pract-03.html#task-3-5-3","kind":"task","label":"Задача 3.5.3","title":"Цилиндр и лента Мёбиуса","text":"Гомеоморфны ли S^1×ℝ и компактная лента Мёбиуса с краем? инварианты сложность 2/5","section":"3.5 Инварианты и негомеоморфность","source":"Листок 3"},{"id":"task-4-1-1","url":"pract/pract-04.html#task-4-1-1","kind":"task","label":"Задача 4.1.1","title":"Три формулировки связности","text":"Докажите эквивалентность: (a) нельзя разбить на два непустых непересекающихся открытых; (b) то же с замкнутыми; (c) открыто-замкнутые только ∅ и X. определения сложность 1/5","section":"4.1 Критерии и примеры связности","source":"Листок 4"},{"id":"task-4-1-2","url":"pract/pract-04.html#task-4-1-2","kind":"task","label":"Задача 4.1.2","title":"Связные подмножества прямой — промежутки","text":"Докажите: A ⊆ ℝ связно ⟺ вместе с любыми a < b из A содержит [a,b]. связность ℝ сложность 3/5 частый тип на КР","section":"4.1 Критерии и примеры связности","source":"Листок 4"},{"id":"task-4-1-3","url":"pract/pract-04.html#task-4-1-3","kind":"task","label":"Задача 4.1.3","title":"Какие подмножества прямой связны","text":"Связны ли {0,1}, [0,1], (-2,-1)∪(1,2), ℚ, ℝ\\ℚ? Для несвязных предъявите разрез. связность сложность 1/5 частый тип на КР","section":"4.1 Критерии и примеры связности","source":"Листок 4"},{"id":"task-4-1-4","url":"pract/pract-04.html#task-4-1-4","kind":"task","label":"Задача 4.1.4","title":"Несвязность через отделённые множества","text":"A ⊆ X несвязно ⟺ A = B ∪ C с непустыми B, C, B ∩ overline C = ∅, C ∩ overline B = ∅ (замыкания в X). связность подмножеств сложность 3/5","section":"4.1 Критерии и примеры связности","source":"Листок 4"},{"id":"task-4-2-1","url":"pract/pract-04.html#task-4-2-1","kind":"task","label":"Задача 4.2.1","title":"Объединение пересекающихся связных","text":"Объединение двух связных множеств с непустым пересечением связно. Обобщите. Lm. 3 сложность 1/5","section":"4.2 Связные множества и непрерывные отображения","source":"Листок 4"},{"id":"task-4-2-2","url":"pract/pract-04.html#task-4-2-2","kind":"task","label":"Задача 4.2.2","title":"Между связным и его замыканием","text":"A связно и A ⊆ B ⊆ overline A. Докажите, что B связно. Связно ли замыкание связного множества? связность сложность 2/5 частый тип на КР","section":"4.2 Связные множества и непрерывные отображения","source":"Листок 4"},{"id":"task-4-2-3","url":"pract/pract-04.html#task-4-2-3","kind":"task","label":"Задача 4.2.3","title":"Граница в связном пространстве непуста","text":"(a) X связно, ∅ ≠ A ≠ X ⇒ ∂_X A ≠ ∅. (b) Связное F пересекает A и X\\ A ⇒ F ∩ ∂_X A ≠ ∅. связность + граница сложность 2/5 частый тип на КР","section":"4.2 Связные множества и непрерывные отображения","source":"Листок 4"},{"id":"task-4-2-4","url":"pract/pract-04.html#task-4-2-4","kind":"task","label":"Задача 4.2.4","title":"Непрерывные оценки и дискретные метки","text":"X непусто и связно, Y — конечное множество меток с дискретной топологией. Докажите, что непрерывное f: X → Y постоянно. А если Y = [0,1]? Th. 4.1 сложность 1/5 частый тип на КР","section":"4.2 Связные множества и непрерывные отображения","source":"Листок 4"},{"id":"task-4-2-5","url":"pract/pract-04.html#task-4-2-5","kind":"task","label":"Задача 4.2.5","title":"Генератор и разделённые кластеры","text":"Z связно, G: Z → ℝ^d непрерывно. Может ли G(Z) лежать в {x_1 ⩽ -1} ∪ {x_1 ⩾ 1} и пересекать обе части? Th. 4.1, Lm. 2 сложность 2/5","section":"4.2 Связные множества и непрерывные отображения","source":"Листок 4"},{"id":"task-4-3-1","url":"pract/pract-04.html#task-4-3-1","kind":"task","label":"Задача 4.3.1","title":"Линейно связное связно","text":"Докажите, что линейно связное пространство связно. Lm. 4 сложность 1/5","section":"4.3 Пути и линейная связность","source":"Листок 4"},{"id":"task-4-3-2","url":"pract/pract-04.html#task-4-3-2","kind":"task","label":"Задача 4.3.2","title":"Нормированная интерполяция на сфере","text":"gamma(t) = dfrac(1-t)x + ty\\|(1-t)x + ty\\|, x, y ∈ S^n-1, n ⩾ 2. Когда это путь? Случай y = -x. Выведите линейную связность S^n-1. пути сложность 2/5","section":"4.3 Пути и линейная связность","source":"Листок 4"},{"id":"task-4-3-3","url":"pract/pract-04.html#task-4-3-3","kind":"task","label":"Задача 4.3.3","title":"Пространство без точки","text":"Докажите, что ℝ^n\\{0} линейно связно при n ⩾ 2. Что при n = 1? пути сложность 2/5 частый тип на КР","section":"4.3 Пути и линейная связность","source":"Листок 4"},{"id":"task-4-4-1","url":"pract/pract-04.html#task-4-4-1","kind":"task","label":"Задача 4.4.1","title":"Открытое подмножество ℝⁿ — многообразие","text":"Любое непустое открытое U ⊆ ℝ^n — n-мерное многообразие. Как устроены координатные окрестности? определение многообразия сложность 2/5","section":"4.4 Карты и компоненты многообразий","source":"Листок 4"},{"id":"task-4-4-2","url":"pract/pract-04.html#task-4-4-2","kind":"task","label":"Задача 4.4.2","title":"Выборка — нульмерное многообразие","text":"Конечная выборка D ⊆ ℝ^n — нульмерное многообразие. Сколько компонент? Сравните размерность с числом признаков. многообразия сложность 1/5","section":"4.4 Карты и компоненты многообразий","source":"Листок 4"},{"id":"task-4-4-3","url":"pract/pract-04.html#task-4-4-3","kind":"task","label":"Задача 4.4.3","title":"Локально конечный атлас","text":"Покрытие областями карт допускает локально конечное уточнение областями карт; у компактного многообразия — конечный податлас. паракомпактность сложность 2/5","section":"4.4 Карты и компоненты многообразий","source":"Листок 4"},{"id":"task-4-4-4","url":"pract/pract-04.html#task-4-4-4","kind":"task","label":"Задача 4.4.4","title":"Связное многообразие линейно связно","text":"У каждой точки многообразия есть линейно связная открытая окрестность. Выведите, что связность равносильна линейной связности, а компоненты открыты и замкнуты. компоненты сложность 3/5 частый тип на КР","section":"4.4 Карты и компоненты многообразий","source":"Листок 4"},{"id":"task-4-4-5","url":"pract/pract-04.html#task-4-4-5","kind":"task","label":"Задача 4.4.5","title":"Компоненты компактного многообразия","text":"Число компонент компактного многообразия конечно. Пример паракомпактного многообразия с несчётным числом компонент. компактность + компоненты сложность 2/5","section":"4.4 Карты и компоненты многообразий","source":"Листок 4"}];
